const DEFAULT_PORT: &str = "8080";
const DATABASE_PATH: &str = "game.db";
const STATE_FORMAT_MAGIC: &[u8] = b"DNDSTATE1";
const STATE_FORMAT_MAGIC_V2: &[u8] = b"DNDSTATE2";
// Request framing limits are intentionally kept at the HTTP boundary so every
// route receives a complete, bounded UTF-8 body.
const MAX_HEADER_BYTES: usize = 16 * 1024;
const MAX_BODY_BYTES: usize = 1024 * 1024;
const REQUEST_READ_BUFFER_BYTES: usize = 4096;
const API_SCHEMA: &str = r#"{"version":"2026-07-29","endpoints":[{"method":"GET","path":"/v1/play/campaigns/{id}/rng-ledger","auth":"member"},{"method":"GET","path":"/v1/schema","auth":"public"},{"method":"POST","path":"/v1/play/campaigns","auth":"dm"},{"method":"POST","path":"/v1/play/campaigns/{id}/fixture-seeds","auth":"dm"},{"method":"POST","path":"/v1/play/campaigns/{id}/members","auth":"member"},{"method":"POST","path":"/v1/play/campaigns/{id}/moderation/reports","auth":"member"},{"method":"POST","path":"/v1/play/campaigns/{id}/rng-rolls","auth":"member"},{"method":"PUT","path":"/v1/play/campaigns/{id}/moderation/reports/{report_id}/resolution","auth":"dm"},{"method":"PUT","path":"/v1/play/campaigns/{id}/rng-seed","auth":"dm"},{"method":"PUT","path":"/v1/play/campaigns/{id}/safety-boundaries","auth":"dm"}]}"#;

/// The service intentionally keeps JSON objects ordered as they appeared in a
/// request.  That lets response construction remain deterministic without a
/// serde dependency.
type JsonObject = Vec<(String, Json)>;
type Sessions = HashMap<String, CombatSession>;
type Users = HashMap<String, User>;

/// A fully buffered HTTP request. Routing owns this value so parsed headers do
/// not borrow the read buffer and route helpers can consume only what they use.
struct HttpRequest {
    method: String,
    path: String,
    body: String,
    authorization: Option<String>,
    idempotency_key: Option<String>,
}

#[derive(Debug)]
enum Json {
    Null,
    Bool(bool),
    Number(i64),
    String(String),
    Array(Vec<Json>),
    Object(JsonObject),
}

