        self.sql(&format!("INSERT INTO play_campaign_agenda_npcs(campaign_id,npc_id,name,agenda,public_status) VALUES ({},{},{},{},{});", sql_text(campaign_id), sql_text(&npc.npc_id), sql_text(&npc.name), sql_text(&npc.agenda), sql_text(&npc.public_status)))?;
        Ok(PlayAgendaNpcResult::Created(PlayAgendaNpc { npc_id: npc.npc_id.clone(), name: npc.name.clone(), agenda: npc.agenda.clone(), public_status: npc.public_status.clone() }))
