    fn create_crafting_project(
        &self,
        campaign_id: &str,
        project: &CraftingProject,
        cost_gp: i64,
    ) -> Result<Option<bool>, ()> {
        if self.campaign(campaign_id)?.is_none() {
            return Ok(None);
        }
        let exists = self.sql(&format!(
            "SELECT 1 FROM crafting_projects WHERE campaign_id = {} AND id = {};",
            sql_text(campaign_id),
            sql_text(&project.id)
        ))?;
        if !exists.trim().is_empty() {
            return Ok(Some(false));
        }
        self.sql(&format!("INSERT INTO crafting_projects(campaign_id,id,character_id,item_slug,days_required,days_completed,cost_gp,status) VALUES ({},{},{},{},{},{},{},{});", sql_text(campaign_id), sql_text(&project.id), sql_text(&project.character_id), sql_text(&project.item_slug), project.days_required, project.days_completed, cost_gp, sql_text(&project.status)))?;
        Ok(Some(true))
    }

    fn crafting_project(
        &self,
        campaign_id: &str,
        project_id: &str,
    ) -> Result<Option<CraftingProject>, ()> {
        let row = self.sql(&format!("SELECT hex(id),hex(character_id),hex(item_slug),days_required,days_completed,hex(status) FROM crafting_projects WHERE campaign_id = {} AND id = {};", sql_text(campaign_id), sql_text(project_id)))?;
        let row = row.trim();
        if row.is_empty() {
            return Ok(None);
        }
        let mut fields = row.split('|');
        let project = CraftingProject {
            id: decode_sql_text(fields.next().ok_or(())?)?,
            character_id: decode_sql_text(fields.next().ok_or(())?)?,
            item_slug: decode_sql_text(fields.next().ok_or(())?)?,
            days_required: fields.next().ok_or(())?.parse().map_err(|_| ())?,
            days_completed: fields.next().ok_or(())?.parse().map_err(|_| ())?,
            status: decode_sql_text(fields.next().ok_or(())?)?,
        };
        if fields.next().is_some() {
            Err(())
        } else {
            Ok(Some(project))
        }
    }

    fn advance_crafting_project(
        &self,
        campaign_id: &str,
        project_id: &str,
        days: i64,
    ) -> Result<Option<CraftingProject>, ()> {
        let Some(mut project) = self.crafting_project(campaign_id, project_id)? else {
            return Ok(None);
        };
        if project.status == "active" {
            project.days_completed = project
                .days_completed
                .checked_add(days)
                .ok_or(())?
                .min(project.days_required);
            if project.days_completed == project.days_required {
                project.status = "complete".to_string();
            }
            let mut statement = format!(
                "BEGIN; UPDATE crafting_projects SET days_completed = {}, status = {} WHERE campaign_id = {} AND id = {};",
                project.days_completed,
                sql_text(&project.status),
                sql_text(campaign_id),
                sql_text(project_id)
            );
            if project.status == "complete" {
                statement.push_str(&format!("INSERT INTO campaign_inventory(campaign_id,item_slug,owner,quantity) VALUES ({},{},'party',1) ON CONFLICT(campaign_id,item_slug,owner) DO UPDATE SET quantity = quantity + excluded.quantity;", sql_text(campaign_id), sql_text(&project.item_slug)));
            }
            statement.push_str("COMMIT;");
            self.sql(&statement)?;
        }
        Ok(Some(project))
    }

    fn create_campaign_session(
        &self,
        campaign_id: &str,
        session: &CampaignSession,
    ) -> Result<Option<bool>, ()> {
        if self.campaign(campaign_id)?.is_none() {
            return Ok(None);
        }
        let exists = self.sql(&format!(
            "SELECT 1 FROM campaign_sessions WHERE campaign_id = {} AND id = {};",
            sql_text(campaign_id),
            sql_text(&session.id)
        ))?;
        if !exists.trim().is_empty() {
            return Ok(Some(false));
        }
        let mut statement = format!(
            "BEGIN; INSERT INTO campaign_sessions(campaign_id,id,starts_at,duration_minutes) VALUES ({},{},{},{});",
            sql_text(campaign_id),
            sql_text(&session.id),
            sql_text(&session.starts_at),
            session.duration_minutes
        );
        for (position, item) in session.agenda.iter().enumerate() {
            statement.push_str(&format!("INSERT INTO campaign_session_agenda(campaign_id,session_id,position,item) VALUES ({},{},{},{});", sql_text(campaign_id), sql_text(&session.id), position, sql_text(item)));
        }
        statement.push_str("COMMIT;");
        self.sql(&statement).map(|_| Some(true))
    }

    fn session_exists(&self, campaign_id: &str, session_id: &str) -> Result<bool, ()> {
        Ok(!self
            .sql(&format!(
                "SELECT 1 FROM campaign_sessions WHERE campaign_id = {} AND id = {};",
                sql_text(campaign_id),
                sql_text(session_id)
            ))?
            .trim()
            .is_empty())
    }

    fn record_session_attendance(
        &self,
        campaign_id: &str,
        session_id: &str,
        present: &[String],
        absent: &[String],
    ) -> Result<bool, ()> {
        if self.campaign(campaign_id)?.is_none() {
            return Ok(false);
        }
        if !self.session_exists(campaign_id, session_id)? {
            return Ok(false);
        }
        let mut statement = format!(
            "BEGIN; DELETE FROM campaign_session_attendance WHERE campaign_id = {} AND session_id = {};",
            sql_text(campaign_id),
            sql_text(session_id)
        );
        for character_id in present {
            statement.push_str(&format!("INSERT INTO campaign_session_attendance(campaign_id,session_id,character_id,status) VALUES ({},{},{},'present');", sql_text(campaign_id), sql_text(session_id), sql_text(character_id)));
        }
        for character_id in absent {
            statement.push_str(&format!("INSERT INTO campaign_session_attendance(campaign_id,session_id,character_id,status) VALUES ({},{},{},'absent');", sql_text(campaign_id), sql_text(session_id), sql_text(character_id)));
        }
        statement.push_str("COMMIT;");
        self.sql(&statement).map(|_| true)
    }

    fn next_campaign_session(&self, campaign_id: &str) -> Result<Option<CampaignSession>, ()> {
        let row = self.sql(&format!("SELECT hex(id),hex(starts_at),duration_minutes FROM campaign_sessions WHERE campaign_id = {} ORDER BY starts_at,id LIMIT 1;", sql_text(campaign_id)))?;
        let row = row.trim();
        if row.is_empty() {
            return Ok(None);
        }
        let mut fields = row.split('|');
        let id = decode_sql_text(fields.next().ok_or(())?)?;
        let starts_at = decode_sql_text(fields.next().ok_or(())?)?;
        let duration_minutes = fields.next().ok_or(())?.parse().map_err(|_| ())?;
        if fields.next().is_some() {
            return Err(());
        }
        let agenda = self.sql(&format!("SELECT hex(item) FROM campaign_session_agenda WHERE campaign_id = {} AND session_id = {} ORDER BY position;", sql_text(campaign_id), sql_text(&id)))?.lines().map(decode_sql_text).collect::<Result<Vec<_>, _>>()?;
        Ok(Some(CampaignSession {
            id,
            starts_at,
            duration_minutes,
            agenda,
        }))
    }

