    fn relationship_summary(&self, campaign_id: &str) -> Result<Option<(i64, i64, i64)>, ()> {
        if self.campaign(campaign_id)?.is_none() {
            return Ok(None);
        }
        let factions = self
            .sql(&format!(
                "SELECT COUNT(*) FROM campaign_factions WHERE campaign_id = {};",
                sql_text(campaign_id)
            ))?
            .trim()
            .parse()
            .map_err(|_| ())?;
        let row = self.sql(&format!(
            "SELECT COUNT(*),SUM(disposition > 0) FROM campaign_npcs WHERE campaign_id = {};",
            sql_text(campaign_id)
        ))?;
        let mut fields = row.trim().split('|');
        let npcs = fields.next().ok_or(())?.parse().map_err(|_| ())?;
        let friendly = match fields.next().ok_or(())? {
            "" => 0,
            value => value.parse().map_err(|_| ())?,
        };
        if fields.next().is_some() {
            return Err(());
        }
        Ok(Some((factions, npcs, friendly)))
    }

