    fn create_quest(&self, campaign_id: &str, quest: &Quest) -> Result<Option<bool>, ()> {
        if self.campaign(campaign_id)?.is_none() {
            return Ok(None);
        }
        let exists = self.sql(&format!(
            "SELECT 1 FROM campaign_quests WHERE campaign_id = {} AND id = {};",
            sql_text(campaign_id),
            sql_text(&quest.id)
        ))?;
        if !exists.trim().is_empty() {
            return Ok(Some(false));
        }
        let mut statement = format!(
            "BEGIN; INSERT INTO campaign_quests(campaign_id,id,title,status) VALUES ({},{},{},{});",
            sql_text(campaign_id),
            sql_text(&quest.id),
            sql_text(&quest.title),
            sql_text(&quest.status)
        );
        for (position, milestone) in quest.milestones.iter().enumerate() {
            statement.push_str(&format!("INSERT INTO quest_milestones(campaign_id,quest_id,title,completed,position) VALUES ({},{},{},0,{});", sql_text(campaign_id), sql_text(&quest.id), sql_text(&milestone.title), position));
        }
        statement.push_str("COMMIT;");
        self.sql(&statement).map(|_| Some(true))
    }

    fn quest(&self, campaign_id: &str, quest_id: &str) -> Result<Option<Quest>, ()> {
        let row = self.sql(&format!("SELECT hex(id),hex(title),hex(status) FROM campaign_quests WHERE campaign_id = {} AND id = {};", sql_text(campaign_id), sql_text(quest_id)))?;
        let row = row.trim();
        if row.is_empty() {
            return Ok(None);
        }
        let mut fields = row.split('|');
        let id = decode_sql_text(fields.next().ok_or(())?)?;
        let title = decode_sql_text(fields.next().ok_or(())?)?;
        let status = decode_sql_text(fields.next().ok_or(())?)?;
        if fields.next().is_some() {
            return Err(());
        }
        let milestones = self.sql(&format!("SELECT hex(title),completed FROM quest_milestones WHERE campaign_id = {} AND quest_id = {} ORDER BY position;", sql_text(campaign_id), sql_text(quest_id)))?
            .lines().map(|line| {
                let mut fields = line.split('|');
                let milestone = QuestMilestone { title: decode_sql_text(fields.next().ok_or(())?)?, completed: match fields.next().ok_or(())? { "0" => false, "1" => true, _ => return Err(()) } };
                if fields.next().is_some() { Err(()) } else { Ok(milestone) }
            }).collect::<Result<Vec<_>, _>>()?;
        Ok(Some(Quest {
            id,
            title,
            status,
            milestones,
        }))
    }

    fn update_quest_progress(
        &self,
        campaign_id: &str,
        quest_id: &str,
        completed: &[String],
    ) -> Result<Option<Quest>, ()> {
        let Some(mut quest) = self.quest(campaign_id, quest_id)? else {
            return Ok(None);
        };
        if completed.iter().any(|title| {
            !quest
                .milestones
                .iter()
                .any(|milestone| milestone.title == *title)
        }) {
            return Err(());
        }
        let mut statement = String::from("BEGIN;");
        for title in completed {
            statement.push_str(&format!("UPDATE quest_milestones SET completed = 1 WHERE campaign_id = {} AND quest_id = {} AND title = {};", sql_text(campaign_id), sql_text(quest_id), sql_text(title)));
        }
        let all_done = !quest.milestones.is_empty()
            && quest.milestones.iter().all(|milestone| {
                milestone.completed || completed.iter().any(|title| title == &milestone.title)
            });
        if all_done && quest.status == "active" {
            statement.push_str(&format!("UPDATE campaign_quests SET status = 'completed' WHERE campaign_id = {} AND id = {};", sql_text(campaign_id), sql_text(quest_id)));
        }
        statement.push_str("COMMIT;");
        self.sql(&statement)?;
        quest = self.quest(campaign_id, quest_id)?.ok_or(())?;
        Ok(Some(quest))
    }

    fn quest_summary(&self, campaign_id: &str) -> Result<Option<(i64, i64, i64)>, ()> {
        if self.campaign(campaign_id)?.is_none() {
            return Ok(None);
        }
        let row = self.sql(&format!("SELECT SUM(status = 'active'),SUM(status = 'completed'),SUM(status = 'blocked') FROM campaign_quests WHERE campaign_id = {};", sql_text(campaign_id)))?;
        let values = row
            .trim()
            .split('|')
            .map(|value| {
                if value.is_empty() {
                    Ok(0)
                } else {
                    value.parse().map_err(|_| ())
                }
            })
            .collect::<Result<Vec<i64>, ()>>()?;
        if values.len() == 3 {
            Ok(Some((values[0], values[1], values[2])))
        } else {
            Err(())
        }
    }

    fn create_monster(&self, monster: &Monster) -> Result<bool, ()> {
        let exists = self.sql(&format!(
            "SELECT 1 FROM monsters WHERE slug = {};",
            sql_text(&monster.slug)
        ))?;
        if !exists.trim().is_empty() {
            return Ok(false);
        }
        let mut statement = format!(
            "BEGIN; INSERT INTO monsters(slug,name,cr,armor_class,hit_points) VALUES ({},{},{},{},{});",
            sql_text(&monster.slug),
            sql_text(&monster.name),
            sql_text(&monster.cr),
            monster.armor_class,
            monster.hit_points,
        );
        for (position, tag) in monster.tags.iter().enumerate() {
            statement.push_str(&format!(
                "INSERT INTO monster_tags(monster_slug,tag,position) VALUES ({},{},{});",
                sql_text(&monster.slug),
                sql_text(tag),
                position
            ));
        }
        statement.push_str("COMMIT;");
        self.sql(&statement).map(|_| true)
    }

    fn monster(&self, slug: &str) -> Result<Option<Monster>, ()> {
        let row = self.sql(&format!("SELECT hex(slug),hex(name),hex(cr),armor_class,hit_points FROM monsters WHERE slug = {};", sql_text(slug)))?;
        let Some(fields) = row.trim().split_once('|') else {
            return Ok(None);
        };
        let mut fields = std::iter::once(fields.0).chain(fields.1.split('|'));
        let slug = decode_sql_text(fields.next().ok_or(())?)?;
        let name = decode_sql_text(fields.next().ok_or(())?)?;
        let cr = decode_sql_text(fields.next().ok_or(())?)?;
        let armor_class = fields.next().ok_or(())?.parse().map_err(|_| ())?;
        let hit_points = fields.next().ok_or(())?.parse().map_err(|_| ())?;
        if fields.next().is_some() {
            return Err(());
        }
        let tags = self
            .sql(&format!(
                "SELECT hex(tag) FROM monster_tags WHERE monster_slug = {} ORDER BY position;",
                sql_text(&slug)
            ))?
            .lines()
            .map(decode_sql_text)
            .collect::<Result<Vec<_>, _>>()?;
        Ok(Some(Monster {
            slug,
            name,
            cr,
            armor_class,
            hit_points,
            tags,
        }))
    }

