fn valid_campaign_text(value: &str) -> bool {
    !value.is_empty() && value.len() <= 1024
}

fn create_campaign(body: &str, storage: &Storage) -> Result<String, CampaignError> {
    let obj = object(body).map_err(|_| CampaignError::Invalid)?;
    let campaign = Campaign {
        id: string_field(&obj, "id")
            .map_err(|_| CampaignError::Invalid)?
            .to_string(),
        name: string_field(&obj, "name")
            .map_err(|_| CampaignError::Invalid)?
            .to_string(),
        dm: string_field(&obj, "dm")
            .map_err(|_| CampaignError::Invalid)?
            .to_string(),
    };
    if !valid_campaign_text(&campaign.id)
        || !valid_campaign_text(&campaign.name)
        || !valid_campaign_text(&campaign.dm)
    {
        return Err(CampaignError::Invalid);
    }
    match storage
        .create_campaign(&campaign)
        .map_err(|_| CampaignError::Storage)?
    {
        true => Ok(campaign_json(&campaign)),
        false => Err(CampaignError::Duplicate),
    }
}

fn create_play_campaign(
    body: &str,
    owner: &str,
    storage: &Storage,
) -> Result<String, PlayCampaignError> {
    let obj = object(body).map_err(|_| PlayCampaignError::Invalid)?;
    let campaign = PlayCampaign {
        id: string_field(&obj, "id")
            .map_err(|_| PlayCampaignError::Invalid)?
            .to_string(),
        name: string_field(&obj, "name")
            .map_err(|_| PlayCampaignError::Invalid)?
            .to_string(),
        owner: owner.to_string(),
        max_players: number_field(&obj, "max_players").map_err(|_| PlayCampaignError::Invalid)?,
    };
    if !valid_campaign_text(&campaign.id)
        || !valid_campaign_text(&campaign.name)
        || !(1..=1000).contains(&campaign.max_players)
    {
        return Err(PlayCampaignError::Invalid);
    }
    match storage
        .create_play_campaign(&campaign)
        .map_err(|_| PlayCampaignError::Storage)?
    {
        true => Ok(format!(
            r#"{{"id":"{}","name":"{}","owner":"{}","status":"lobby","max_players":{}}}"#,
            escape_json(&campaign.id),
            escape_json(&campaign.name),
            escape_json(&campaign.owner),
            campaign.max_players
        )),
        false => Err(PlayCampaignError::Duplicate),
    }
}

fn valid_campaign_document_text(value: &str) -> bool {
    value.len() <= 16_384
}

fn update_play_campaign_document(
    campaign_id: &str,
    owner: &str,
    body: &str,
    storage: &Storage,
) -> Result<String, PlayCampaignDocumentError> {
    if !valid_campaign_text(campaign_id) {
        return Err(PlayCampaignDocumentError::Invalid);
    }
    let obj = object(body).map_err(|_| PlayCampaignDocumentError::Invalid)?;
    let document = PlayCampaignDocument {
        story: string_field(&obj, "story")
            .map_err(|_| PlayCampaignDocumentError::Invalid)?
            .to_string(),
        dm_notes: string_field(&obj, "dm_notes")
            .map_err(|_| PlayCampaignDocumentError::Invalid)?
            .to_string(),
    };
    if !valid_campaign_document_text(&document.story)
        || !valid_campaign_document_text(&document.dm_notes)
    {
        return Err(PlayCampaignDocumentError::Invalid);
    }
    match storage
        .update_play_campaign_document(campaign_id, owner, &document)
        .map_err(|_| PlayCampaignDocumentError::Storage)?
    {
        PlayCampaignDocumentUpdate::Updated => Ok(format!(
            r#"{{"story":"{}","dm_notes":"{}"}}"#,
            escape_json(&document.story),
            escape_json(&document.dm_notes)
        )),
        PlayCampaignDocumentUpdate::UnknownCampaign => {
            Err(PlayCampaignDocumentError::UnknownCampaign)
        }
        PlayCampaignDocumentUpdate::Forbidden => Err(PlayCampaignDocumentError::Forbidden),
    }
}

fn get_play_campaign_document(
    campaign_id: &str,
    actor: &str,
    include_dm_notes: bool,
    storage: &Storage,
) -> Result<String, PlayCampaignDocumentError> {
    if !valid_campaign_text(campaign_id) {
        return Err(PlayCampaignDocumentError::Invalid);
    }
    match storage
        .play_campaign_document(campaign_id, actor, include_dm_notes)
        .map_err(|_| PlayCampaignDocumentError::Storage)?
    {
        PlayCampaignDocumentRead::Found(document) if include_dm_notes => Ok(format!(
            r#"{{"story":"{}","dm_notes":"{}"}}"#,
            escape_json(&document.story),
            escape_json(&document.dm_notes)
        )),
        PlayCampaignDocumentRead::Found(document) => {
            Ok(format!(r#"{{"story":"{}"}}"#, escape_json(&document.story)))
        }
        PlayCampaignDocumentRead::UnknownCampaign => {
            Err(PlayCampaignDocumentError::UnknownCampaign)
        }
        PlayCampaignDocumentRead::Forbidden => Err(PlayCampaignDocumentError::Forbidden),
    }
}

