fn get_play_campaign_onboarding(
    campaign_id: &str,
    actor: &str,
    storage: &Storage,
) -> Result<String, PlayOnboardingError> {
    if !valid_campaign_text(campaign_id) {
        return Err(PlayOnboardingError::UnknownCampaign);
    }
    let owner = storage
        .sql(&format!(
            "SELECT hex(owner) FROM play_campaigns WHERE id = {};",
            sql_text(campaign_id)
        ))
        .map_err(|_| PlayOnboardingError::Storage)?;
    let owner = owner.trim();
    if owner.is_empty() {
        return Err(PlayOnboardingError::UnknownCampaign);
    }
    let owner = decode_sql_text(owner).map_err(|_| PlayOnboardingError::Storage)?;
    let is_owner = owner == actor;
    let is_member = !storage
        .sql(&format!(
            "SELECT 1 FROM play_campaign_members WHERE campaign_id = {} AND username = {};",
            sql_text(campaign_id),
            sql_text(actor)
        ))
        .map_err(|_| PlayOnboardingError::Storage)?
        .trim()
        .is_empty();
    if !is_owner && !is_member {
        return Err(PlayOnboardingError::Forbidden);
    }
    if is_owner {
        Ok(r#"{"role":"dm","next_steps":["configure-safety","invite-players","start-campaign"],"can_mutate":true}"#.to_string())
    } else {
        Ok(r#"{"role":"player","next_steps":["review-party","take-turn","submit-action"],"can_mutate":true}"#.to_string())
    }
}

fn authenticated_spectator(authorization: Option<&str>) -> Option<&str> {
    let id = authorization?.strip_prefix("Bearer spectator-")?;
    if id.is_empty() { return None; }
    Some(id)
}

fn create_play_spectator(
    campaign_id: &str,
    actor: &str,
    body: &str,
    storage: &Storage,
) -> Result<String, PlaySpectatorRouteError> {
    if !valid_campaign_text(campaign_id) {
        return Err(PlaySpectatorRouteError::UnknownCampaign);
    }
    let obj = object(body).map_err(|_| PlaySpectatorRouteError::Invalid)?;
    let spectator_id = string_field(&obj, "spectator_id")
        .map_err(|_| PlaySpectatorRouteError::Invalid)?;
    if spectator_id.is_empty() {
        return Err(PlaySpectatorRouteError::Invalid);
    }
    match storage
        .create_play_spectator(campaign_id, actor, spectator_id)
        .map_err(|_| PlaySpectatorRouteError::Storage)?
    {
        PlaySpectatorResult::Created(token) => Ok(format!(
            r#"{{"spectator_id":"{}","token":"{}"}}"#,
            escape_json(spectator_id),
            escape_json(&token)
        )),
        PlaySpectatorResult::Duplicate => Err(PlaySpectatorRouteError::Duplicate),
        PlaySpectatorResult::UnknownCampaign => Err(PlaySpectatorRouteError::UnknownCampaign),
        PlaySpectatorResult::Forbidden => Err(PlaySpectatorRouteError::Forbidden),
    }
}

fn get_play_spectator_view(
    campaign_id: &str,
    spectator_id: &str,
    storage: &Storage,
) -> Result<String, PlaySpectatorViewRouteError> {
    if !valid_campaign_text(campaign_id) {
        return Err(PlaySpectatorViewRouteError::UnknownCampaign);
    }
    match storage
        .play_spectator_view(campaign_id, spectator_id)
        .map_err(|_| PlaySpectatorViewRouteError::Storage)?
    {
        PlaySpectatorViewResult::Found(response) => Ok(response),
        PlaySpectatorViewResult::UnknownCampaign => Err(PlaySpectatorViewRouteError::UnknownCampaign),
        PlaySpectatorViewResult::Forbidden => Err(PlaySpectatorViewRouteError::Forbidden),
        PlaySpectatorViewResult::Unauthorized => Err(PlaySpectatorViewRouteError::Unauthorized),
    }
}

fn play_campaign_backup_row(row: &str) -> Result<PlayCampaignBackup, ()> {
    let mut fields = row.split('|');
    let backup = PlayCampaignBackup {
        backup_id: decode_sql_text(fields.next().ok_or(())?)?,
        story: decode_sql_text(fields.next().ok_or(())?)?,
        status: decode_sql_text(fields.next().ok_or(())?)?,
    };
    if fields.next().is_some() { return Err(()); }
    Ok(backup)
}

fn play_campaign_backup_json(backup: &PlayCampaignBackup) -> String {
    format!(r#"{{"backup_id":"{}","story":"{}","status":"{}"}}"#, escape_json(&backup.backup_id), escape_json(&backup.story), escape_json(&backup.status))
}

fn create_play_campaign_backup(campaign_id: &str, actor: &str, storage: &Storage) -> Result<String, PlayCampaignBackupResult> {
    if !valid_campaign_text(campaign_id) { return Err(PlayCampaignBackupResult::Missing); }
    match storage.create_play_campaign_backup(campaign_id, actor).map_err(|_| PlayCampaignBackupResult::Missing)? {
        PlayCampaignBackupResult::Created(backup) => Ok(play_campaign_backup_json(&backup)),
        result => Err(result),
    }
}

fn get_play_campaign_backups(campaign_id: &str, actor: &str, storage: &Storage) -> Result<String, PlayCampaignBackupResult> {
    if !valid_campaign_text(campaign_id) { return Err(PlayCampaignBackupResult::Missing); }
    match storage.play_campaign_backups(campaign_id, actor).map_err(|_| PlayCampaignBackupResult::Missing)? {
        PlayCampaignBackupResult::Listed(backups) => Ok(format!(r#"{{"backups":[{}]}}"#, backups.iter().map(play_campaign_backup_json).collect::<Vec<_>>().join(","))),
        result => Err(result),
    }
}

fn restore_play_campaign_backup(campaign_id: &str, actor: &str, backup_id: &str, storage: &Storage) -> Result<String, PlayCampaignBackupResult> {
    if !valid_campaign_text(campaign_id) || backup_id.is_empty() || backup_id.contains('/') { return Err(PlayCampaignBackupResult::Missing); }
    match storage.restore_play_campaign_backup(campaign_id, actor, backup_id).map_err(|_| PlayCampaignBackupResult::Missing)? {
        PlayCampaignBackupResult::Found(backup) => Ok(play_campaign_backup_json(&backup)),
        result => Err(result),
    }
}

fn play_campaign_backup_response(result: Result<String, PlayCampaignBackupResult>, stream: &mut TcpStream, status: u16) -> std::io::Result<()> {
    match result {
        Ok(response) => respond(stream, status, &response),
        Err(PlayCampaignBackupResult::UnknownCampaign | PlayCampaignBackupResult::Missing) => respond(stream, 404, r#"{"error":"not found"}"#),
        Err(PlayCampaignBackupResult::Forbidden) => respond(stream, 403, r#"{"error":"forbidden"}"#),
        Err(_) => respond(stream, 500, r#"{"error":"storage failure"}"#),
    }
}

