fn play_campaign_import_row(row: &str) -> Result<PlayCampaignImport, ()> {
    let mut fields = row.split('|');
    let snapshot = PlayCampaignImport {
        version: fields.next().ok_or(())?.parse().map_err(|_| ())?,
        story: decode_sql_text(fields.next().ok_or(())?)?,
        status: decode_sql_text(fields.next().ok_or(())?)?,
    };
    if fields.next().is_some() { return Err(()); }
    Ok(snapshot)
}

fn play_campaign_import_json(snapshot: &PlayCampaignImport) -> String {
    format!(r#"{{"version":{},"story":"{}","status":"{}"}}"#, snapshot.version, escape_json(&snapshot.story), escape_json(&snapshot.status))
}

fn parse_play_campaign_import(body: &str) -> Result<PlayCampaignImport, ()> {
    let obj = object(body)?;
    if obj.len() != 3 || ["version", "story", "status"].iter().any(|name| obj.iter().filter(|(key, _)| key == name).count() != 1) {
        return Err(());
    }
    let version = number_field(&obj, "version")?;
    let story = string_field(&obj, "story")?.to_string();
    let status = string_field(&obj, "status")?.to_string();
    if version != 1 || story.is_empty() || !matches!(status.as_str(), "lobby" | "started") {
        return Err(());
    }
    Ok(PlayCampaignImport { version, story, status })
}

fn import_play_campaign(campaign_id: &str, actor: &str, body: &str, storage: &Storage) -> Result<String, PlayCampaignImportResult> {
    if !valid_campaign_text(campaign_id) { return Err(PlayCampaignImportResult::Missing); }
    match storage.play_campaign_export_owner(campaign_id, actor).map_err(|_| PlayCampaignImportResult::Missing)? {
        PlayCampaignExportAccess::Allowed => {}
        PlayCampaignExportAccess::UnknownCampaign => return Err(PlayCampaignImportResult::UnknownCampaign),
        PlayCampaignExportAccess::Forbidden => return Err(PlayCampaignImportResult::Forbidden),
    }
    let snapshot = parse_play_campaign_import(body).map_err(|_| PlayCampaignImportResult::Invalid)?;
    match storage.import_play_campaign(campaign_id, actor, &snapshot).map_err(|_| PlayCampaignImportResult::Missing)? {
        PlayCampaignImportResult::Applied(snapshot) => Ok(play_campaign_import_json(&snapshot)),
        result => Err(result),
    }
}

fn get_play_campaign_import(campaign_id: &str, actor: &str, storage: &Storage) -> Result<String, PlayCampaignImportResult> {
    if !valid_campaign_text(campaign_id) { return Err(PlayCampaignImportResult::Missing); }
    match storage.play_campaign_import(campaign_id, actor).map_err(|_| PlayCampaignImportResult::Missing)? {
        PlayCampaignImportResult::Found(snapshot) => Ok(play_campaign_import_json(&snapshot)),
        result => Err(result),
    }
}

