fn parse_feed_query(query: &str) -> Result<(i64, i64), ()> {
    let mut cursor: Option<i64> = None;
    let mut limit: Option<i64> = None;
    if !query.is_empty() {
        for part in query.split('&') {
            let (name, value) = part.split_once('=').ok_or(())?;
            match name {
                "cursor" if cursor.is_none() => { cursor = Some(value.parse::<i64>().map_err(|_| ())?); }
                "limit" if limit.is_none() => { limit = Some(value.parse::<i64>().map_err(|_| ())?); }
                _ => return Err(()),
            }
        }
    }
    let cursor = cursor.unwrap_or(0);
    let limit = limit.unwrap_or(2);
    if cursor < 0 || !(1..=3).contains(&limit) { return Err(()); }
    Ok((cursor, limit))
}

fn create_play_feed_event(campaign_id: &str, actor: &str, body: &str, storage: &Storage) -> Result<String, PlayFeedEventError> {
    if !valid_campaign_text(campaign_id) { return Err(PlayFeedEventError::UnknownCampaign); }
    let obj = object(body).map_err(|_| PlayFeedEventError::Invalid)?;
    let event_id = string_field(&obj, "event_id").map_err(|_| PlayFeedEventError::Invalid)?;
    let text = string_field(&obj, "text").map_err(|_| PlayFeedEventError::Invalid)?;
    if event_id.is_empty() || text.is_empty() { return Err(PlayFeedEventError::Invalid); }
    let sequence = storage.create_play_feed_event(campaign_id, actor, event_id, text)?;
    Ok(format!(r#"{{"event_id":"{}","text":"{}","sequence":{}}}"#, escape_json(event_id), escape_json(text), sequence))
}

fn get_play_feed_events(campaign_id: &str, actor: &str, query: &str, storage: &Storage) -> Result<String, PlayFeedEventError> {
    if !valid_campaign_text(campaign_id) { return Err(PlayFeedEventError::UnknownCampaign); }
    let (cursor, limit) = parse_feed_query(query).map_err(|_| PlayFeedEventError::Invalid)?;
    let (events, next_cursor) = storage.play_feed_events(campaign_id, actor, cursor, limit)?;
    Ok(format!(r#"{{"events":[{}],"next_cursor":{}}}"#, events.iter().map(|event| format!(r#"{{"event_id":"{}","text":"{}","sequence":{}}}"#, escape_json(&event.event_id), escape_json(&event.text), event.sequence)).collect::<Vec<_>>().join(","), next_cursor))
}

