enum PlayProjectionError { Invalid, UnknownCampaign, Forbidden, Conflict, Storage }

fn projection_event_json(event: &PlayProjectionEvent) -> String {
    match &event.value {
        Some(value) => format!(r#"{{"sequence":{},"event_id":"{}","kind":"{}","value":"{}"}}"#, event.sequence, escape_json(&event.event_id), event.kind, escape_json(value)),
        None => format!(r#"{{"sequence":{},"event_id":"{}","kind":"{}"}}"#, event.sequence, escape_json(&event.event_id), event.kind),
    }
}

fn projection_json(events: &[PlayProjectionEvent]) -> String {
    let mut story = "";
    let mut danger = 0;
    for event in events {
        if event.kind == "set-story" { story = event.value.as_deref().unwrap_or(""); } else { danger += 1; }
    }
    format!(r#"{{"story":"{}","danger":{},"applied_event_ids":[{}]}}"#, escape_json(story), danger, events.iter().map(|event| format!(r#""{}""#, escape_json(&event.event_id))).collect::<Vec<_>>().join(","))
}

fn append_play_projection_event(campaign_id: &str, actor: &str, body: &str, storage: &Storage) -> Result<String, PlayProjectionError> {
    if !valid_campaign_text(campaign_id) { return Err(PlayProjectionError::Invalid); }
    let obj = object(body).map_err(|_| PlayProjectionError::Invalid)?;
    let event_id = string_field(&obj, "event_id").map_err(|_| PlayProjectionError::Invalid)?;
    let kind = string_field(&obj, "kind").map_err(|_| PlayProjectionError::Invalid)?;
    if event_id.is_empty() || !matches!(kind, "set-story" | "increment-danger") { return Err(PlayProjectionError::Invalid); }
    let value = obj.iter().find(|(name, _)| name == "value").map(|(_, value)| match value { Json::String(value) if !value.is_empty() => Ok(value.as_str()), _ => Err(PlayProjectionError::Invalid) }).transpose()?;
    if (kind == "set-story" && (obj.len() != 3 || value.is_none())) || (kind == "increment-danger" && (obj.len() != 2 || value.is_some())) { return Err(PlayProjectionError::Invalid); }
    match storage.append_play_projection_event(campaign_id, actor, event_id, kind, value).map_err(|_| PlayProjectionError::Storage)? {
        PlayProjectionResult::Found(event) => Ok(projection_event_json(&event)),
        PlayProjectionResult::UnknownCampaign => Err(PlayProjectionError::UnknownCampaign),
        PlayProjectionResult::Forbidden => Err(PlayProjectionError::Forbidden),
        PlayProjectionResult::Conflict => Err(PlayProjectionError::Conflict),
    }
}

fn get_play_projection(campaign_id: &str, actor: &str, storage: &Storage) -> Result<String, PlayProjectionError> {
    if !valid_campaign_text(campaign_id) { return Err(PlayProjectionError::Invalid); }
    match storage.play_projection(campaign_id, actor).map_err(|_| PlayProjectionError::Storage)? {
        PlayProjectionResult::Found(events) => Ok(projection_json(&events)),
        PlayProjectionResult::UnknownCampaign => Err(PlayProjectionError::UnknownCampaign),
        PlayProjectionResult::Forbidden => Err(PlayProjectionError::Forbidden),
        PlayProjectionResult::Conflict => Err(PlayProjectionError::Storage),
    }
}

