#[derive(Debug)]
enum PlayModerationError { Invalid, UnknownCampaign, Forbidden, Missing, Conflict, Storage }

fn play_moderation_report_row(row: &str) -> Result<PlayModerationReport, ()> {
    let mut fields = row.split('|');
    let sequence = fields.next().ok_or(())?.parse().map_err(|_| ())?;
    let report_id = decode_sql_text(fields.next().ok_or(())?)?;
    let target_id = decode_sql_text(fields.next().ok_or(())?)?;
    let reason = decode_sql_text(fields.next().ok_or(())?)?;
    let status = decode_sql_text(fields.next().ok_or(())?)?;
    let reporter = decode_sql_text(fields.next().ok_or(())?)?;
    let optional = |value: &str| if value.is_empty() { Ok(None) } else { decode_sql_text(value).map(Some) };
    let action = optional(fields.next().ok_or(())?)?;
    let note = optional(fields.next().ok_or(())?)?;
    let resolver = optional(fields.next().ok_or(())?)?;
    if fields.next().is_some() { return Err(()); }
    Ok(PlayModerationReport { report_id, target_id, reason, status, reporter, sequence, action, note, resolver })
}

fn moderation_report_json(report: &PlayModerationReport) -> String {
    let mut json = format!(r#"{{"report_id":"{}","target_id":"{}","reason":"{}","status":"{}","reporter":"{}","sequence":{}}}"#, escape_json(&report.report_id), escape_json(&report.target_id), escape_json(&report.reason), escape_json(&report.status), escape_json(&report.reporter), report.sequence);
    if let (Some(action), Some(note), Some(resolver)) = (&report.action, &report.note, &report.resolver) {
        json.pop();
        json.push_str(&format!(r#","action":"{}","note":"{}","resolver":"{}"}}"#, escape_json(action), escape_json(note), escape_json(resolver)));
    }
    json
}

fn create_play_moderation_report(campaign_id: &str, actor: &str, body: &str, storage: &Storage) -> Result<String, PlayModerationError> {
    if !valid_campaign_text(campaign_id) { return Err(PlayModerationError::Invalid); }
    let obj = object(body).map_err(|_| PlayModerationError::Invalid)?;
    if obj.len() != 3 { return Err(PlayModerationError::Invalid); }
    let report_id = string_field(&obj, "report_id").map_err(|_| PlayModerationError::Invalid)?;
    let target_id = string_field(&obj, "target_id").map_err(|_| PlayModerationError::Invalid)?;
    let reason = string_field(&obj, "reason").map_err(|_| PlayModerationError::Invalid)?;
    if report_id.is_empty() || target_id.is_empty() || reason.is_empty() { return Err(PlayModerationError::Invalid); }
    match storage.create_play_moderation_report(campaign_id, actor, report_id, target_id, reason).map_err(|_| PlayModerationError::Storage)? {
        PlayModerationResult::Created(report) => Ok(moderation_report_json(&report)),
        PlayModerationResult::UnknownCampaign => Err(PlayModerationError::UnknownCampaign),
        PlayModerationResult::Forbidden => Err(PlayModerationError::Forbidden),
        PlayModerationResult::Conflict => Err(PlayModerationError::Conflict),
        _ => Err(PlayModerationError::Storage),
    }
}

fn get_play_moderation_reports(campaign_id: &str, actor: &str, storage: &Storage) -> Result<String, PlayModerationError> {
    if !valid_campaign_text(campaign_id) { return Err(PlayModerationError::Invalid); }
    match storage.play_moderation_reports(campaign_id, actor).map_err(|_| PlayModerationError::Storage)? {
        PlayModerationResult::Listed(reports) => Ok(format!(r#"{{"reports":[{}]}}"#, reports.iter().map(moderation_report_json).collect::<Vec<_>>().join(","))),
        PlayModerationResult::UnknownCampaign => Err(PlayModerationError::UnknownCampaign),
        PlayModerationResult::Forbidden => Err(PlayModerationError::Forbidden),
        _ => Err(PlayModerationError::Storage),
    }
}

fn resolve_play_moderation_report(campaign_id: &str, actor: &str, report_id: &str, body: &str, storage: &Storage) -> Result<String, PlayModerationError> {
    if !valid_campaign_text(campaign_id) || report_id.is_empty() || report_id.contains('/') { return Err(PlayModerationError::Invalid); }
    let obj = object(body).map_err(|_| PlayModerationError::Invalid)?;
    if obj.len() != 2 { return Err(PlayModerationError::Invalid); }
    let action = string_field(&obj, "action").map_err(|_| PlayModerationError::Invalid)?;
    let note = string_field(&obj, "note").map_err(|_| PlayModerationError::Invalid)?;
    if !matches!(action, "allow" | "remove") || note.is_empty() { return Err(PlayModerationError::Invalid); }
    match storage.resolve_play_moderation_report(campaign_id, actor, report_id, action, note).map_err(|_| PlayModerationError::Storage)? {
        PlayModerationResult::Resolved(report) => Ok(moderation_report_json(&report)),
        PlayModerationResult::UnknownCampaign => Err(PlayModerationError::UnknownCampaign),
        PlayModerationResult::Forbidden => Err(PlayModerationError::Forbidden),
        PlayModerationResult::Missing => Err(PlayModerationError::Missing),
        PlayModerationResult::Conflict => Err(PlayModerationError::Conflict),
        _ => Err(PlayModerationError::Storage),
    }
}

fn moderation_response(result: Result<String, PlayModerationError>, stream: &mut TcpStream, status: u16) -> std::io::Result<()> {
    match result {
        Ok(body) => respond(stream, status, &body),
        Err(PlayModerationError::Invalid) => respond(stream, 400, r#"{"error":"invalid request"}"#),
        Err(PlayModerationError::UnknownCampaign | PlayModerationError::Missing) => respond(stream, 404, r#"{"error":"not found"}"#),
        Err(PlayModerationError::Forbidden) => respond(stream, 403, r#"{"error":"forbidden"}"#),
        Err(PlayModerationError::Conflict) => respond(stream, 409, r#"{"error":"conflict"}"#),
        Err(PlayModerationError::Storage) => respond(stream, 500, r#"{"error":"storage failure"}"#),
    }
}

#[derive(Debug)]
enum PlaySafetyError { Invalid, UnknownCampaign, Forbidden, Conflict, Storage }

fn valid_unique_tags(tags: &[String]) -> bool {
    !tags.is_empty() && tags.iter().all(|tag| !tag.trim().is_empty()) && tags.iter().collect::<HashSet<_>>().len() == tags.len()
}

fn safety_tags_json(tags: &[String]) -> String {
    format!(r#"{{"blocked_tags":[{}]}}"#, tags.iter().map(|tag| format!(r#""{}""#, escape_json(tag))).collect::<Vec<_>>().join(","))
}

fn safety_event_json(event: &PlaySafetyEvent) -> String {
    format!(r#"{{"event_id":"{}","kind":"{}","text":"{}","tags":[{}],"sequence":{}}}"#, escape_json(&event.event_id), escape_json(&event.kind), escape_json(&event.text), event.tags.iter().map(|tag| format!(r#""{}""#, escape_json(tag))).collect::<Vec<_>>().join(","), event.sequence)
}

fn replace_play_safety_boundaries(campaign_id: &str, actor: &str, body: &str, storage: &Storage) -> Result<String, PlaySafetyError> {
    if !valid_campaign_text(campaign_id) { return Err(PlaySafetyError::Invalid); }
    let obj = object(body).map_err(|_| PlaySafetyError::Invalid)?;
    if obj.len() != 1 { return Err(PlaySafetyError::Invalid); }
    let mut tags = string_array_field(&obj, "blocked_tags").map_err(|_| PlaySafetyError::Invalid)?;
    if !valid_unique_tags(&tags) { return Err(PlaySafetyError::Invalid); }
    tags.sort();
    match storage.replace_play_safety_boundaries(campaign_id, actor, &tags).map_err(|_| PlaySafetyError::Storage)? {
        PlaySafetyResult::Found(tags) => Ok(safety_tags_json(&tags)),
        PlaySafetyResult::UnknownCampaign => Err(PlaySafetyError::UnknownCampaign),
        PlaySafetyResult::Forbidden => Err(PlaySafetyError::Forbidden),
        PlaySafetyResult::Conflict => Err(PlaySafetyError::Storage),
    }
}

fn get_play_safety_boundaries(campaign_id: &str, actor: &str, storage: &Storage) -> Result<String, PlaySafetyError> {
    if !valid_campaign_text(campaign_id) { return Err(PlaySafetyError::Invalid); }
    match storage.play_safety_boundaries(campaign_id, actor).map_err(|_| PlaySafetyError::Storage)? {
        PlaySafetyResult::Found(tags) => Ok(safety_tags_json(&tags)),
        PlaySafetyResult::UnknownCampaign => Err(PlaySafetyError::UnknownCampaign),
        PlaySafetyResult::Forbidden => Err(PlaySafetyError::Forbidden),
        PlaySafetyResult::Conflict => Err(PlaySafetyError::Storage),
    }
}

fn submit_play_safety_check(campaign_id: &str, actor: &str, body: &str, storage: &Storage) -> Result<String, PlaySafetyError> {
    if !valid_campaign_text(campaign_id) { return Err(PlaySafetyError::Invalid); }
    let obj = object(body).map_err(|_| PlaySafetyError::Invalid)?;
    if obj.len() != 4 { return Err(PlaySafetyError::Invalid); }
    let event_id = string_field(&obj, "event_id").map_err(|_| PlaySafetyError::Invalid)?;
    let kind = string_field(&obj, "kind").map_err(|_| PlaySafetyError::Invalid)?;
    let text = string_field(&obj, "text").map_err(|_| PlaySafetyError::Invalid)?;
    let tags = string_array_field(&obj, "tags").map_err(|_| PlaySafetyError::Invalid)?;
    if event_id.is_empty() || text.is_empty() || !matches!(kind, "narration" | "chat") || !valid_unique_tags(&tags) { return Err(PlaySafetyError::Invalid); }
    match storage.submit_play_safety_check(campaign_id, actor, event_id, kind, text, &tags).map_err(|_| PlaySafetyError::Storage)? {
        PlaySafetyResult::Found(event) => Ok(safety_event_json(&event)),
        PlaySafetyResult::UnknownCampaign => Err(PlaySafetyError::UnknownCampaign),
        PlaySafetyResult::Forbidden => Err(PlaySafetyError::Forbidden),
        PlaySafetyResult::Conflict => Err(PlaySafetyError::Conflict),
    }
}

fn get_play_safety_events(campaign_id: &str, actor: &str, storage: &Storage) -> Result<String, PlaySafetyError> {
    if !valid_campaign_text(campaign_id) { return Err(PlaySafetyError::Invalid); }
    match storage.play_safety_events(campaign_id, actor).map_err(|_| PlaySafetyError::Storage)? {
        PlaySafetyResult::Found(events) => Ok(format!(r#"{{"events":[{}]}}"#, events.iter().map(safety_event_json).collect::<Vec<_>>().join(","))),
        PlaySafetyResult::UnknownCampaign => Err(PlaySafetyError::UnknownCampaign),
        PlaySafetyResult::Forbidden => Err(PlaySafetyError::Forbidden),
        PlaySafetyResult::Conflict => Err(PlaySafetyError::Storage),
    }
}

fn safety_response(result: Result<String, PlaySafetyError>, stream: &mut TcpStream, status: u16) -> std::io::Result<()> {
    match result {
        Ok(body) => respond(stream, status, &body),
        Err(PlaySafetyError::Invalid) => respond(stream, 400, r#"{"error":"invalid request"}"#),
        Err(PlaySafetyError::UnknownCampaign) => respond(stream, 404, r#"{"error":"not found"}"#),
        Err(PlaySafetyError::Forbidden) => respond(stream, 403, r#"{"error":"forbidden"}"#),
        Err(PlaySafetyError::Conflict) => respond(stream, 409, r#"{"error":"conflict"}"#),
        Err(PlaySafetyError::Storage) => respond(stream, 500, r#"{"error":"storage failure"}"#),
    }
}

