enum PlayIdempotentError { Invalid, UnknownCampaign, Forbidden, Conflict, Storage }

fn idempotent_event_json(event: &PlayIdempotentEvent) -> String {
    format!(r#"{{"event_id":"{}","value":"{}","sequence":{},"idempotency_key":"{}"}}"#, escape_json(&event.event_id), escape_json(&event.value), event.sequence, escape_json(&event.idempotency_key))
}

fn create_play_idempotent_event(campaign_id: &str, actor: &str, body: &str, idempotency_key: Option<&str>, storage: &Storage) -> Result<(String, bool), PlayIdempotentError> {
    if !valid_campaign_text(campaign_id) { return Err(PlayIdempotentError::Invalid); }
    let idempotency_key = idempotency_key.map(str::trim).filter(|key| !key.is_empty()).ok_or(PlayIdempotentError::Invalid)?;
    let obj = object(body).map_err(|_| PlayIdempotentError::Invalid)?;
    if obj.len() != 2 { return Err(PlayIdempotentError::Invalid); }
    let event_id = string_field(&obj, "event_id").map_err(|_| PlayIdempotentError::Invalid)?;
    let value = string_field(&obj, "value").map_err(|_| PlayIdempotentError::Invalid)?;
    if event_id.is_empty() || value.is_empty() { return Err(PlayIdempotentError::Invalid); }
    match storage.create_play_idempotent_event(campaign_id, actor, event_id, value, idempotency_key).map_err(|_| PlayIdempotentError::Storage)? {
        PlayIdempotentResult::Created(event) => Ok((idempotent_event_json(&event), true)),
        PlayIdempotentResult::Replayed(event) => Ok((idempotent_event_json(&event), false)),
        PlayIdempotentResult::UnknownCampaign => Err(PlayIdempotentError::UnknownCampaign),
        PlayIdempotentResult::Forbidden => Err(PlayIdempotentError::Forbidden),
        PlayIdempotentResult::Conflict => Err(PlayIdempotentError::Conflict),
    }
}

fn get_play_idempotent_events(campaign_id: &str, actor: &str, storage: &Storage) -> Result<(String, bool), PlayIdempotentError> {
    if !valid_campaign_text(campaign_id) { return Err(PlayIdempotentError::Invalid); }
    match storage.play_idempotent_events(campaign_id, actor).map_err(|_| PlayIdempotentError::Storage)? {
        PlayIdempotentResult::Created(events) => Ok((format!(r#"{{"events":[{}]}}"#, events.iter().map(idempotent_event_json).collect::<Vec<_>>().join(",")), false)),
        PlayIdempotentResult::Replayed(_) => Err(PlayIdempotentError::Storage),
        PlayIdempotentResult::UnknownCampaign => Err(PlayIdempotentError::UnknownCampaign),
        PlayIdempotentResult::Forbidden => Err(PlayIdempotentError::Forbidden),
        PlayIdempotentResult::Conflict => Err(PlayIdempotentError::Conflict),
    }
}

fn idempotent_event_response(result: Result<(String, bool), PlayIdempotentError>, stream: &mut TcpStream) -> std::io::Result<()> {
    match result {
        Ok((body, true)) => respond(stream, 201, &body),
        Ok((body, false)) => respond(stream, 200, &body),
        Err(PlayIdempotentError::Invalid) => respond(stream, 400, r#"{"error":"invalid request"}"#),
        Err(PlayIdempotentError::UnknownCampaign) => respond(stream, 404, r#"{"error":"not found"}"#),
        Err(PlayIdempotentError::Forbidden) => respond(stream, 403, r#"{"error":"forbidden"}"#),
        Err(PlayIdempotentError::Conflict) => respond(stream, 409, r#"{"error":"conflict"}"#),
        Err(PlayIdempotentError::Storage) => respond(stream, 500, r#"{"error":"storage failure"}"#),
    }
}

#[derive(Debug)]
enum PlaySafeTurnError { Invalid, UnknownCampaign, Forbidden, Duplicate, Stale(i64), Storage }

fn safe_turn_json(turn: &PlaySafeTurn) -> String {
    format!(r#"{{"submission_id":"{}","action":"{}","accepted_turn":{},"next_turn":{}}}"#, escape_json(&turn.submission_id), escape_json(&turn.action), turn.accepted_turn, turn.next_turn)
}

fn submit_play_safe_turn(campaign_id: &str, actor: &str, body: &str, storage: &Storage) -> Result<String, PlaySafeTurnError> {
    if !valid_campaign_text(campaign_id) { return Err(PlaySafeTurnError::Invalid); }
    let obj = object(body).map_err(|_| PlaySafeTurnError::Invalid)?;
    if obj.len() != 3 { return Err(PlaySafeTurnError::Invalid); }
    let submission_id = string_field(&obj, "submission_id").map_err(|_| PlaySafeTurnError::Invalid)?;
    let expected_turn = number_field(&obj, "expected_turn").map_err(|_| PlaySafeTurnError::Invalid)?;
    let action = string_field(&obj, "action").map_err(|_| PlaySafeTurnError::Invalid)?;
    if submission_id.is_empty() || action.is_empty() || expected_turn <= 0 { return Err(PlaySafeTurnError::Invalid); }
    match storage.submit_play_safe_turn(campaign_id, actor, submission_id, expected_turn, action).map_err(|_| PlaySafeTurnError::Storage)? {
        PlaySafeTurnResult::Submitted(turn) => Ok(safe_turn_json(&turn)),
        PlaySafeTurnResult::Stale { current_turn } => Err(PlaySafeTurnError::Stale(current_turn)),
        PlaySafeTurnResult::UnknownCampaign => Err(PlaySafeTurnError::UnknownCampaign),
        PlaySafeTurnResult::Forbidden => Err(PlaySafeTurnError::Forbidden),
        PlaySafeTurnResult::Duplicate => Err(PlaySafeTurnError::Duplicate),
        PlaySafeTurnResult::Found { .. } => Err(PlaySafeTurnError::Storage),
    }
}

fn get_play_safe_turns(campaign_id: &str, actor: &str, storage: &Storage) -> Result<String, PlaySafeTurnError> {
    if !valid_campaign_text(campaign_id) { return Err(PlaySafeTurnError::Invalid); }
    match storage.play_safe_turns(campaign_id, actor).map_err(|_| PlaySafeTurnError::Storage)? {
        PlaySafeTurnResult::Found { current_turn, accepted } => Ok(format!(r#"{{"current_turn":{},"accepted":[{}]}}"#, current_turn, accepted.iter().map(safe_turn_json).collect::<Vec<_>>().join(","))),
        PlaySafeTurnResult::UnknownCampaign => Err(PlaySafeTurnError::UnknownCampaign),
        PlaySafeTurnResult::Forbidden => Err(PlaySafeTurnError::Forbidden),
        _ => Err(PlaySafeTurnError::Storage),
    }
}

fn safe_turn_response(result: Result<String, PlaySafeTurnError>, stream: &mut TcpStream, success_status: u16) -> std::io::Result<()> {
    match result {
        Ok(body) => respond(stream, success_status, &body),
        Err(PlaySafeTurnError::Invalid) => respond(stream, 400, r#"{"error":"invalid request"}"#),
        Err(PlaySafeTurnError::UnknownCampaign) => respond(stream, 404, r#"{"error":"not found"}"#),
        Err(PlaySafeTurnError::Forbidden) => respond(stream, 403, r#"{"error":"forbidden"}"#),
        Err(PlaySafeTurnError::Duplicate) => respond(stream, 409, r#"{"error":"conflict"}"#),
        Err(PlaySafeTurnError::Stale(current_turn)) => respond(stream, 409, &format!(r#"{{"current_turn":{current_turn}}}"#)),
        Err(PlaySafeTurnError::Storage) => respond(stream, 500, r#"{"error":"storage failure"}"#),
    }
}

fn grant_play_delegation(campaign_id: &str, actor: &str, body: &str, storage: &Storage) -> Result<String, PlayDelegationError> {
    if !valid_campaign_text(campaign_id) { return Err(PlayDelegationError::Invalid); }
    let obj = object(body).map_err(|_| PlayDelegationError::Invalid)?;
    let username = string_field(&obj, "username").map_err(|_| PlayDelegationError::Invalid)?;
    let powers = string_array_field(&obj, "powers").map_err(|_| PlayDelegationError::Invalid)?;
    let mut unique = std::collections::HashSet::new();
    if !valid_username(username) || powers.is_empty() || !powers.iter().all(|power| power == "narrate" && unique.insert(power)) {
        return Err(PlayDelegationError::Invalid);
    }
    match storage.grant_play_delegation(campaign_id, actor, username).map_err(|_| PlayDelegationError::Storage)? {
        PlayDelegationResult::Found(delegation) => Ok(delegation_json(&delegation)),
        PlayDelegationResult::UnknownCampaign => Err(PlayDelegationError::UnknownCampaign),
        PlayDelegationResult::Forbidden => Err(PlayDelegationError::Forbidden),
        PlayDelegationResult::Missing => Err(PlayDelegationError::Invalid),
        PlayDelegationResult::Conflict => Err(PlayDelegationError::Conflict),
    }
}

