/// This compact PHB wizard-spell catalog is the validation boundary for the
/// play API.  A spellbook stores the caller's supplied display name, while the
/// stable spell id and level are checked here.
fn is_wizard_spell(spell_id: &str, name: &str, level: i64) -> bool {
    if matches!(spell_id, "fire-bolt" | "magic-missile")
        && !matches!(
            (spell_id, name),
            ("fire-bolt", "Fire Bolt") | ("magic-missile", "Magic Missile")
        )
    {
        return false;
    }
    matches!(
        (spell_id, level),
        ("acid-splash", 0)
            | ("blade-ward", 0)
            | ("chill-touch", 0)
            | ("fire-bolt", 0)
            | ("light", 0)
            | ("mage-hand", 0)
            | ("minor-illusion", 0)
            | ("poison-spray", 0)
            | ("prestidigitation", 0)
            | ("ray-of-frost", 0)
            | ("shocking-grasp", 0)
            | ("true-strike", 0)
            | ("burning-hands", 1)
            | ("charm-person", 1)
            | ("detect-magic", 1)
            | ("disguise-self", 1)
            | ("feather-fall", 1)
            | ("find-familiar", 1)
            | ("identify", 1)
            | ("mage-armor", 1)
            | ("magic-missile", 1)
            | ("shield", 1)
            | ("sleep", 1)
            | ("thunderwave", 1)
            | ("invisibility", 2)
            | ("misty-step", 2)
            | ("scorching-ray", 2)
            | ("web", 2)
            | ("counterspell", 3)
            | ("fireball", 3)
            | ("fly", 3)
            | ("haste", 3)
            | ("lightning-bolt", 3)
            | ("dimension-door", 4)
            | ("greater-invisibility", 4)
            | ("polymorph", 4)
            | ("wall-of-fire", 4)
            | ("animate-objects", 5)
            | ("cone-of-cold", 5)
            | ("scrying", 5)
            | ("teleportation-circle", 5)
            | ("chain-lightning", 6)
            | ("disintegrate", 6)
            | ("globe-of-invulnerability", 6)
            | ("teleport", 7)
            | ("finger-of-death", 7)
            | ("plane-shift", 7)
            | ("dominate-monster", 8)
            | ("maze", 8)
            | ("power-word-stun", 8)
            | ("foresight", 9)
            | ("meteor-swarm", 9)
            | ("power-word-kill", 9)
            | ("time-stop", 9)
            | ("wish", 9)
    )
}

