fn play_recipe_json(recipe: &PlayRecipe) -> String {
    format!(
        r#"{{"recipe_id":"{}","name":"{}","ingredients":{{{}}},"output_item":"{}","output_quantity":{}}}"#,
        escape_json(&recipe.recipe_id),
        escape_json(&recipe.name),
        recipe.ingredients.iter().map(|(item_id, quantity)| format!(r#""{}":{}"#, escape_json(item_id), quantity)).collect::<Vec<_>>().join(","),
        escape_json(&recipe.output_item),
        recipe.output_quantity,
    )
}

fn parse_play_recipe(body: &str) -> Result<PlayRecipe, PlayRecipeError> {
    let obj = object(body).map_err(|_| PlayRecipeError::Invalid)?;
    let recipe_id = string_field(&obj, "recipe_id").map_err(|_| PlayRecipeError::Invalid)?.to_string();
    let name = string_field(&obj, "name").map_err(|_| PlayRecipeError::Invalid)?.to_string();
    let output_item = string_field(&obj, "output_item").map_err(|_| PlayRecipeError::Invalid)?.to_string();
    let output_quantity = number_field(&obj, "output_quantity").map_err(|_| PlayRecipeError::Invalid)?;
    let ingredient_object = as_object(field(&obj, "ingredients").map_err(|_| PlayRecipeError::Invalid)?).map_err(|_| PlayRecipeError::Invalid)?;
    if !valid_campaign_text(&recipe_id) || !valid_campaign_text(&name) || !valid_play_inventory_item(&output_item) || output_quantity <= 0 || ingredient_object.is_empty() {
        return Err(PlayRecipeError::Invalid);
    }
    let mut ingredients = Vec::new();
    let mut seen = std::collections::HashSet::new();
    for (item_id, value) in ingredient_object {
        let Json::Number(quantity) = value else { return Err(PlayRecipeError::Invalid); };
        if !valid_play_inventory_item(item_id) || *quantity <= 0 || !seen.insert(item_id) { return Err(PlayRecipeError::Invalid); }
        ingredients.push((item_id.clone(), *quantity));
    }
    Ok(PlayRecipe { recipe_id, name, ingredients, output_item, output_quantity })
}

fn create_play_recipe(campaign_id: &str, actor: &str, body: &str, storage: &Storage) -> Result<String, PlayRecipeError> {
    if !valid_campaign_text(campaign_id) { return Err(PlayRecipeError::Invalid); }
    let recipe = parse_play_recipe(body)?;
    match storage.create_play_recipe(campaign_id, actor, &recipe).map_err(|_| PlayRecipeError::Storage)? {
        PlayRecipeResult::Created(recipe) => Ok(play_recipe_json(&recipe)),
        PlayRecipeResult::UnknownCampaign => Err(PlayRecipeError::UnknownCampaign),
        PlayRecipeResult::Forbidden => Err(PlayRecipeError::Forbidden),
        PlayRecipeResult::Conflict => Err(PlayRecipeError::Conflict),
        _ => Err(PlayRecipeError::Storage),
    }
}

fn get_play_recipes(campaign_id: &str, actor: &str, storage: &Storage) -> Result<String, PlayRecipeError> {
    if !valid_campaign_text(campaign_id) { return Err(PlayRecipeError::Invalid); }
    match storage.play_recipes(campaign_id, actor).map_err(|_| PlayRecipeError::Storage)? {
        PlayRecipeResult::Listed(recipes) => Ok(format!(r#"{{"recipes":[{}]}}"#, recipes.iter().map(play_recipe_json).collect::<Vec<_>>().join(","))),
        PlayRecipeResult::UnknownCampaign => Err(PlayRecipeError::UnknownCampaign),
        PlayRecipeResult::Forbidden => Err(PlayRecipeError::Forbidden),
        _ => Err(PlayRecipeError::Storage),
    }
}

fn craft_play_recipe(campaign_id: &str, actor: &str, recipe_id: &str, body: &str, storage: &Storage) -> Result<String, PlayRecipeError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(recipe_id) { return Err(PlayRecipeError::Invalid); }
    let obj = object(body).map_err(|_| PlayRecipeError::Invalid)?;
    let character_id = string_field(&obj, "character_id").map_err(|_| PlayRecipeError::Invalid)?;
    if !valid_campaign_text(character_id) { return Err(PlayRecipeError::Invalid); }
    match storage.craft_play_recipe(campaign_id, actor, recipe_id, character_id).map_err(|_| PlayRecipeError::Storage)? {
        PlayRecipeResult::Crafted => {
            let recipe = storage.play_recipes(campaign_id, actor).map_err(|_| PlayRecipeError::Storage)?;
            let PlayRecipeResult::Listed(recipes) = recipe else { return Err(PlayRecipeError::Storage); };
            let recipe = recipes.iter().find(|recipe| recipe.recipe_id == recipe_id).ok_or(PlayRecipeError::Storage)?;
            Ok(format!(r#"{{"character_id":"{}","recipe_id":"{}","output_item":"{}","output_quantity":{}}}"#, escape_json(character_id), escape_json(recipe_id), escape_json(&recipe.output_item), recipe.output_quantity))
        }
        PlayRecipeResult::UnknownCampaign => Err(PlayRecipeError::UnknownCampaign),
        PlayRecipeResult::Forbidden => Err(PlayRecipeError::Forbidden),
        PlayRecipeResult::Missing => Err(PlayRecipeError::Missing),
        PlayRecipeResult::Conflict => Err(PlayRecipeError::Conflict),
        _ => Err(PlayRecipeError::Storage),
    }
}

fn play_recipe_response(result: Result<String, PlayRecipeError>, stream: &mut TcpStream, success_status: u16) -> std::io::Result<()> {
    match result {
        Ok(response) => respond(stream, success_status, &response),
        Err(PlayRecipeError::Invalid) => respond(stream, 400, r#"{"error":"invalid request"}"#),
        Err(PlayRecipeError::UnknownCampaign | PlayRecipeError::Missing) => respond(stream, 404, r#"{"error":"not found"}"#),
        Err(PlayRecipeError::Forbidden) => respond(stream, 403, r#"{"error":"forbidden"}"#),
        Err(PlayRecipeError::Conflict) => respond(stream, 409, r#"{"error":"conflict"}"#),
        Err(PlayRecipeError::Storage) => respond(stream, 500, r#"{"error":"storage failure"}"#),
    }
}

