    if include_agenda {
        format!(r#"{{"npc_id":"{}","name":"{}","agenda":"{}","public_status":"{}"}}"#, escape_json(&npc.npc_id), escape_json(&npc.name), escape_json(&npc.agenda), escape_json(&npc.public_status))
    } else {
        format!(r#"{{"npc_id":"{}","name":"{}","public_status":"{}"}}"#, escape_json(&npc.npc_id), escape_json(&npc.name), escape_json(&npc.public_status))
    }
