fn create_play_agenda_npc(campaign_id: &str, actor: &str, body: &str, storage: &Storage) -> Result<String, PlayAgendaNpcError> {
    if !valid_campaign_text(campaign_id) { return Err(PlayAgendaNpcError::Invalid); }
    let obj = object(body).map_err(|_| PlayAgendaNpcError::Invalid)?;
    let npc = PlayAgendaNpc {
        npc_id: string_field(&obj, "npc_id").map_err(|_| PlayAgendaNpcError::Invalid)?.to_string(),
        name: string_field(&obj, "name").map_err(|_| PlayAgendaNpcError::Invalid)?.to_string(),
        agenda: string_field(&obj, "agenda").map_err(|_| PlayAgendaNpcError::Invalid)?.to_string(),
        public_status: string_field(&obj, "public_status").map_err(|_| PlayAgendaNpcError::Invalid)?.to_string(),
    };
    if !valid_campaign_text(&npc.npc_id) || !valid_campaign_text(&npc.name) || !valid_campaign_text(&npc.agenda) || !valid_campaign_text(&npc.public_status) { return Err(PlayAgendaNpcError::Invalid); }
    match storage.create_play_agenda_npc(campaign_id, actor, &npc).map_err(|_| PlayAgendaNpcError::Storage)? {
        PlayAgendaNpcResult::Created(npc) => Ok(agenda_npc_json(&npc, true)),
        PlayAgendaNpcResult::UnknownCampaign => Err(PlayAgendaNpcError::UnknownCampaign),
        PlayAgendaNpcResult::Forbidden => Err(PlayAgendaNpcError::Forbidden),
        PlayAgendaNpcResult::Conflict => Err(PlayAgendaNpcError::Conflict),
        _ => Err(PlayAgendaNpcError::Storage),
    }
}

