fn play_clue_json(clue: &PlayClue) -> String {
    let base = format!(r#"{{"clue_id":"{}","text":"{}","audience":"{}""#, escape_json(&clue.clue_id), escape_json(&clue.text), escape_json(&clue.audience));
    match &clue.character_id {
        Some(character_id) => format!(r#"{base},"character_id":"{}"}}"#, escape_json(character_id)),
        None => format!(r#"{base}}}"#),
    }
}

fn create_play_clue(campaign_id: &str, actor: &str, body: &str, storage: &Storage) -> Result<String, PlayClueError> {
    if !valid_campaign_text(campaign_id) { return Err(PlayClueError::Invalid); }
    let obj = object(body).map_err(|_| PlayClueError::Invalid)?;
    let clue_id = string_field(&obj, "clue_id").map_err(|_| PlayClueError::Invalid)?.to_string();
    let text = string_field(&obj, "text").map_err(|_| PlayClueError::Invalid)?.to_string();
    let audience = string_field(&obj, "audience").map_err(|_| PlayClueError::Invalid)?.to_string();
    if !valid_campaign_text(&clue_id) || !valid_campaign_text(&text) { return Err(PlayClueError::Invalid); }
    let character_id = match audience.as_str() {
        "character" => Some(string_field(&obj, "character_id").map_err(|_| PlayClueError::Invalid)?.to_string()),
        "party" | "hidden" => {
            if field(&obj, "character_id").is_ok() { return Err(PlayClueError::Invalid); }
            None
        }
        _ => return Err(PlayClueError::Invalid),
    };
    if character_id.as_deref().is_some_and(|value| !valid_campaign_text(value)) { return Err(PlayClueError::Invalid); }
    let clue = PlayClue { clue_id, text, audience, character_id };
    match storage.create_play_clue(campaign_id, actor, &clue).map_err(|_| PlayClueError::Storage)? {
        PlayClueResult::Created(clue) => Ok(play_clue_json(&clue)),
        PlayClueResult::UnknownCampaign => Err(PlayClueError::UnknownCampaign),
        PlayClueResult::Forbidden => Err(PlayClueError::Forbidden),
        PlayClueResult::Invalid => Err(PlayClueError::Invalid),
        PlayClueResult::Conflict => Err(PlayClueError::Conflict),
        _ => Err(PlayClueError::Storage),
    }
}

