fn play_quest_json(quest: &PlayQuest) -> String {
    let rewards = quest.rewards.as_ref().map(play_quest_rewards_json).map(|value| format!(",\"rewards\":{value}")).unwrap_or_default();
    format!(r#"{{"quest_id":"{}","title":"{}","depends_on":[{}],"state":"{}"{}}}"#, escape_json(&quest.quest_id), escape_json(&quest.title), quest.depends_on.iter().map(|dependency| format!(r#""{}""#, escape_json(dependency))).collect::<Vec<_>>().join(","), escape_json(&quest.state), rewards)
}

fn play_quest_rewards_json(rewards: &PlayQuestRewards) -> String {
    format!(r#"{{"xp":{},"items":{{{}}}}}"#, rewards.xp, rewards.items.iter().map(|(item, quantity)| format!(r#""{}":{}"#, escape_json(item), quantity)).collect::<Vec<_>>().join(","))
}

fn parse_play_quest_rewards(body: &str) -> Result<PlayQuestRewards, PlayQuestError> {
    let obj = object(body).map_err(|_| PlayQuestError::Invalid)?;
    let xp = number_field(&obj, "xp").map_err(|_| PlayQuestError::Invalid)?;
    let items = as_object(field(&obj, "items").map_err(|_| PlayQuestError::Invalid)?).map_err(|_| PlayQuestError::Invalid)?;
    if xp < 0 { return Err(PlayQuestError::Invalid); }
    let mut seen = std::collections::HashSet::new();
    let mut values = Vec::new();
    for (item, value) in items { let Json::Number(quantity) = value else { return Err(PlayQuestError::Invalid); }; if !valid_play_inventory_item(item) || *quantity <= 0 || !seen.insert(item) { return Err(PlayQuestError::Invalid); } values.push((item.clone(), *quantity)); }
    Ok(PlayQuestRewards { xp, items: values })
}

fn configure_play_quest_rewards(campaign_id: &str, actor: &str, quest_id: &str, body: &str, storage: &Storage) -> Result<String, PlayQuestError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(quest_id) { return Err(PlayQuestError::Invalid); }
    let rewards = parse_play_quest_rewards(body)?;
    match storage.configure_play_quest_rewards(campaign_id, actor, quest_id, &rewards).map_err(|_| PlayQuestError::Storage)? { PlayQuestRewardsResult::Configured(quest) => Ok(play_quest_json(&quest)), PlayQuestRewardsResult::UnknownCampaign => Err(PlayQuestError::UnknownCampaign), PlayQuestRewardsResult::Forbidden => Err(PlayQuestError::Forbidden), PlayQuestRewardsResult::Missing => Err(PlayQuestError::Missing), PlayQuestRewardsResult::Conflict => Err(PlayQuestError::Conflict), _ => Err(PlayQuestError::Storage) }
}

fn award_play_quest_rewards(campaign_id: &str, actor: &str, quest_id: &str, storage: &Storage) -> Result<String, PlayQuestError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(quest_id) { return Err(PlayQuestError::Invalid); }
    match storage.award_play_quest_rewards(campaign_id, actor, quest_id).map_err(|_| PlayQuestError::Storage)? { PlayQuestRewardsResult::Awarded(rewards) => Ok(format!(r#"{{"quest_id":"{}","awarded":true,"xp":{},"items":{{{}}}}}"#, escape_json(quest_id), rewards.xp, rewards.items.iter().map(|(item, quantity)| format!(r#""{}":{}"#, escape_json(item), quantity)).collect::<Vec<_>>().join(","))), PlayQuestRewardsResult::UnknownCampaign => Err(PlayQuestError::UnknownCampaign), PlayQuestRewardsResult::Forbidden => Err(PlayQuestError::Forbidden), PlayQuestRewardsResult::Missing => Err(PlayQuestError::Missing), PlayQuestRewardsResult::Conflict => Err(PlayQuestError::Conflict), _ => Err(PlayQuestError::Storage) }
}

