fn play_world_event_json(event: &PlayWorldEvent) -> String {
    let (status, resolution) = match &event.resolution {
        Some(resolution) => ("resolved", format!(r#","resolution":{{"turn_number":{},"text":"{}"}}"#, resolution.turn_number, escape_json(&resolution.text))),
        None => ("scheduled", String::new()),
    };
    format!(r#"{{"event_id":"{}","turn_number":{},"title":"{}","text":"{}","status":"{}"{}}}"#, escape_json(&event.event_id), event.turn_number, escape_json(&event.title), escape_json(&event.text), status, resolution)
}

fn create_play_world_event(campaign_id: &str, actor: &str, body: &str, storage: &Storage) -> Result<String, PlayWorldEventError> {
    if !valid_campaign_text(campaign_id) { return Err(PlayWorldEventError::Invalid); }
    let obj = object(body).map_err(|_| PlayWorldEventError::Invalid)?;
    let event = PlayWorldEvent {
        event_id: string_field(&obj, "event_id").map_err(|_| PlayWorldEventError::Invalid)?.to_string(),
        turn_number: number_field(&obj, "turn_number").map_err(|_| PlayWorldEventError::Invalid)?,
        title: string_field(&obj, "title").map_err(|_| PlayWorldEventError::Invalid)?.to_string(),
        text: string_field(&obj, "text").map_err(|_| PlayWorldEventError::Invalid)?.to_string(),
        resolution: None,
    };
    if !valid_campaign_text(&event.event_id) || !valid_campaign_text(&event.title) || !valid_campaign_text(&event.text) || event.turn_number < 1 { return Err(PlayWorldEventError::Invalid); }
    match storage.create_play_world_event(campaign_id, actor, &event).map_err(|_| PlayWorldEventError::Storage)? {
        PlayWorldEventResult::Created(event) => Ok(play_world_event_json(&event)),
        PlayWorldEventResult::UnknownCampaign => Err(PlayWorldEventError::UnknownCampaign),
        PlayWorldEventResult::Forbidden => Err(PlayWorldEventError::Forbidden),
        PlayWorldEventResult::Invalid => Err(PlayWorldEventError::Invalid),
        PlayWorldEventResult::Conflict => Err(PlayWorldEventError::Conflict),
        _ => Err(PlayWorldEventError::Storage),
    }
}

fn resolve_play_world_event(campaign_id: &str, actor: &str, event_id: &str, body: &str, storage: &Storage) -> Result<String, PlayWorldEventError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(event_id) { return Err(PlayWorldEventError::Invalid); }
    let obj = object(body).map_err(|_| PlayWorldEventError::Invalid)?;
    let text = string_field(&obj, "text").map_err(|_| PlayWorldEventError::Invalid)?;
    if !valid_campaign_text(text) { return Err(PlayWorldEventError::Invalid); }
    match storage.resolve_play_world_event(campaign_id, actor, event_id, text).map_err(|_| PlayWorldEventError::Storage)? {
        PlayWorldEventResult::Resolved(event) => Ok(play_world_event_json(&event)),
        PlayWorldEventResult::UnknownCampaign => Err(PlayWorldEventError::UnknownCampaign),
        PlayWorldEventResult::Forbidden => Err(PlayWorldEventError::Forbidden),
        PlayWorldEventResult::Missing => Err(PlayWorldEventError::Missing),
        PlayWorldEventResult::Conflict => Err(PlayWorldEventError::Conflict),
        _ => Err(PlayWorldEventError::Storage),
    }
}

