fn shop_json(shop: &PlayShop) -> String {
    format!(r#"{{"shop_id":"{}","name":"{}","stock":{{{}}},"buy_price":{},"sell_price":{}}}"#, escape_json(&shop.shop_id), escape_json(&shop.name), shop.stock.iter().map(|(item, quantity)| format!(r#""{}":{}"#, escape_json(item), quantity)).collect::<Vec<_>>().join(","), shop.buy_price, shop.sell_price)
}

fn shop_from_body(body: &str) -> Result<PlayShop, PlayShopError> {
    let obj = object(body).map_err(|_| PlayShopError::Invalid)?;
    let shop_id = string_field(&obj, "shop_id").map_err(|_| PlayShopError::Invalid)?.to_string();
    let name = string_field(&obj, "name").map_err(|_| PlayShopError::Invalid)?.to_string();
    let buy_price = number_field(&obj, "buy_price").map_err(|_| PlayShopError::Invalid)?;
    let sell_price = number_field(&obj, "sell_price").map_err(|_| PlayShopError::Invalid)?;
    let stock_value = obj.iter().find(|(key, _)| key == "stock").map(|(_, value)| value).ok_or(PlayShopError::Invalid)?;
    let Json::Object(entries) = stock_value else { return Err(PlayShopError::Invalid); };
    if !valid_campaign_text(&shop_id) || !valid_campaign_text(&name) || buy_price <= 0 || sell_price < 0 || entries.is_empty() { return Err(PlayShopError::Invalid); }
    let mut stock = Vec::new();
    for (item_id, value) in entries { let Json::Number(quantity) = value else { return Err(PlayShopError::Invalid); }; if !valid_play_inventory_item(item_id) || *quantity <= 0 || stock.iter().any(|(seen, _)| seen == item_id) { return Err(PlayShopError::Invalid); } stock.push((item_id.clone(), *quantity)); }
    Ok(PlayShop { shop_id, name, stock, buy_price, sell_price })
}

fn create_play_shop(campaign_id: &str, actor: &str, settlement_id: &str, body: &str, storage: &Storage) -> Result<String, PlayShopError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(settlement_id) { return Err(PlayShopError::Invalid); }
    let shop = shop_from_body(body)?;
    match storage.create_play_shop(campaign_id, actor, settlement_id, &shop).map_err(|_| PlayShopError::Storage)? { PlayShopResult::Created(shop) => Ok(shop_json(&shop)), PlayShopResult::UnknownCampaign => Err(PlayShopError::UnknownCampaign), PlayShopResult::Forbidden => Err(PlayShopError::Forbidden), PlayShopResult::Missing => Err(PlayShopError::Missing), PlayShopResult::Conflict => Err(PlayShopError::Conflict), _ => Err(PlayShopError::Storage) }
}

fn get_play_shop(campaign_id: &str, actor: &str, settlement_id: &str, shop_id: &str, storage: &Storage) -> Result<String, PlayShopError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(settlement_id) || !valid_campaign_text(shop_id) { return Err(PlayShopError::Invalid); }
    match storage.get_play_shop(campaign_id, actor, settlement_id, shop_id).map_err(|_| PlayShopError::Storage)? { PlayShopResult::Found(shop) => Ok(shop_json(&shop)), PlayShopResult::UnknownCampaign => Err(PlayShopError::UnknownCampaign), PlayShopResult::Forbidden => Err(PlayShopError::Forbidden), PlayShopResult::Missing => Err(PlayShopError::Missing), _ => Err(PlayShopError::Storage) }
}

fn trade_play_shop(campaign_id: &str, actor: &str, settlement_id: &str, shop_id: &str, body: &str, buying: bool, storage: &Storage) -> Result<String, PlayShopError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(settlement_id) || !valid_campaign_text(shop_id) { return Err(PlayShopError::Invalid); }
    let obj = object(body).map_err(|_| PlayShopError::Invalid)?;
    let character_id = string_field(&obj, "character_id").map_err(|_| PlayShopError::Invalid)?;
    let item_id = string_field(&obj, "item_id").map_err(|_| PlayShopError::Invalid)?;
    let quantity = number_field(&obj, "quantity").map_err(|_| PlayShopError::Invalid)?;
    if !valid_campaign_text(character_id) || !valid_play_inventory_item(item_id) || quantity <= 0 { return Err(PlayShopError::Invalid); }
    match storage.trade_play_shop(campaign_id, actor, settlement_id, shop_id, character_id, item_id, quantity, buying).map_err(|_| PlayShopError::Storage)? { PlayShopResult::Traded { gold, stock } => Ok(format!(r#"{{"character_id":"{}","item_id":"{}","quantity":{},"gold":{},"stock":{}}}"#, escape_json(character_id), escape_json(item_id), quantity, gold, stock)), PlayShopResult::UnknownCampaign => Err(PlayShopError::UnknownCampaign), PlayShopResult::Forbidden => Err(PlayShopError::Forbidden), PlayShopResult::Missing => Err(PlayShopError::Missing), PlayShopResult::Conflict => Err(PlayShopError::Conflict), _ => Err(PlayShopError::Storage) }
}

fn play_shop_response(result: Result<String, PlayShopError>, stream: &mut TcpStream, status: u16) -> std::io::Result<()> {
    match result { Ok(response) => respond(stream, status, &response), Err(PlayShopError::Invalid) => respond(stream, 400, r#"{"error":"invalid request"}"#), Err(PlayShopError::UnknownCampaign | PlayShopError::Missing) => respond(stream, 404, r#"{"error":"not found"}"#), Err(PlayShopError::Forbidden) => respond(stream, 403, r#"{"error":"forbidden"}"#), Err(PlayShopError::Conflict) => respond(stream, 409, r#"{"error":"conflict"}"#), Err(PlayShopError::Storage) => respond(stream, 500, r#"{"error":"storage failure"}"#) }
}

fn play_faction_json(faction: &PlayFaction) -> String {
    format!(r#"{{"faction_id":"{}","name":"{}"}}"#, escape_json(&faction.faction_id), escape_json(&faction.name))
}

fn faction_reputation_json(entry: &PlayFactionReputation) -> String {
    format!(r#"{{"faction_id":"{}","character_id":"{}","reputation":{},"delta":{},"reason":"{}"}}"#, escape_json(&entry.faction_id), escape_json(&entry.character_id), entry.reputation, entry.delta, escape_json(&entry.reason))
}

fn create_play_faction(campaign_id: &str, actor: &str, body: &str, storage: &Storage) -> Result<String, PlayFactionError> {
    if !valid_campaign_text(campaign_id) { return Err(PlayFactionError::Invalid); }
    let obj = object(body).map_err(|_| PlayFactionError::Invalid)?;
    let faction = PlayFaction {
        faction_id: string_field(&obj, "faction_id").map_err(|_| PlayFactionError::Invalid)?.to_string(),
        name: string_field(&obj, "name").map_err(|_| PlayFactionError::Invalid)?.to_string(),
    };
    if !valid_campaign_text(&faction.faction_id) || !valid_campaign_text(&faction.name) { return Err(PlayFactionError::Invalid); }
    match storage.create_play_faction(campaign_id, actor, &faction).map_err(|_| PlayFactionError::Storage)? {
        PlayFactionResult::Created(faction) => Ok(play_faction_json(&faction)),
        PlayFactionResult::UnknownCampaign => Err(PlayFactionError::UnknownCampaign),
        PlayFactionResult::Forbidden => Err(PlayFactionError::Forbidden),
        PlayFactionResult::Conflict => Err(PlayFactionError::Conflict),
        _ => Err(PlayFactionError::Storage),
    }
}

fn change_play_faction_reputation(campaign_id: &str, actor: &str, faction_id: &str, body: &str, storage: &Storage) -> Result<String, PlayFactionError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(faction_id) { return Err(PlayFactionError::Invalid); }
    let obj = object(body).map_err(|_| PlayFactionError::Invalid)?;
    let character_id = string_field(&obj, "character_id").map_err(|_| PlayFactionError::Invalid)?;
    let delta = number_field(&obj, "delta").map_err(|_| PlayFactionError::Invalid)?;
    let reason = string_field(&obj, "reason").map_err(|_| PlayFactionError::Invalid)?;
    if !valid_campaign_text(character_id) || !valid_campaign_text(reason) || delta == 0 || !(-25..=25).contains(&delta) { return Err(PlayFactionError::Invalid); }
    match storage.change_play_faction_reputation(campaign_id, actor, faction_id, character_id, delta, reason).map_err(|_| PlayFactionError::Storage)? {
        PlayFactionResult::ReputationChanged(entry) => Ok(faction_reputation_json(&entry)),
        PlayFactionResult::UnknownCampaign => Err(PlayFactionError::UnknownCampaign),
        PlayFactionResult::Forbidden => Err(PlayFactionError::Forbidden),
        PlayFactionResult::Missing => Err(PlayFactionError::Missing),
        PlayFactionResult::InvalidCharacter => Err(PlayFactionError::Invalid),
        _ => Err(PlayFactionError::Storage),
    }
}

fn get_play_faction_reputation(campaign_id: &str, actor: &str, faction_id: &str, storage: &Storage) -> Result<String, PlayFactionError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(faction_id) { return Err(PlayFactionError::Invalid); }
    match storage.play_faction_reputation_history(campaign_id, actor, faction_id).map_err(|_| PlayFactionError::Storage)? {
        PlayFactionResult::ReputationHistory(entries) => Ok(format!(r#"{{"faction_id":"{}","entries":[{}]}}"#, escape_json(faction_id), entries.iter().map(faction_reputation_json).collect::<Vec<_>>().join(","))),
        PlayFactionResult::UnknownCampaign => Err(PlayFactionError::UnknownCampaign),
        PlayFactionResult::Forbidden => Err(PlayFactionError::Forbidden),
        PlayFactionResult::Missing => Err(PlayFactionError::Missing),
        _ => Err(PlayFactionError::Storage),
    }
}

fn play_faction_response(result: Result<String, PlayFactionError>, stream: &mut TcpStream, success_status: u16) -> std::io::Result<()> {
    match result {
        Ok(response) => respond(stream, success_status, &response),
        Err(PlayFactionError::Invalid) => respond(stream, 400, r#"{"error":"invalid request"}"#),
        Err(PlayFactionError::UnknownCampaign | PlayFactionError::Missing) => respond(stream, 404, r#"{"error":"not found"}"#),
        Err(PlayFactionError::Forbidden) => respond(stream, 403, r#"{"error":"forbidden"}"#),
        Err(PlayFactionError::Conflict) => respond(stream, 409, r#"{"error":"conflict"}"#),
        Err(PlayFactionError::Storage) => respond(stream, 500, r#"{"error":"storage failure"}"#),
    }
}

fn build_play_character(
    campaign_id: &str,
    actor: &str,
    character_id: &str,
    body: &str,
    storage: &Storage,
) -> Result<String, PlayCharacterBuildError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(character_id) {
        return Err(PlayCharacterBuildError::Invalid);
    }
    match storage
        .play_character_owner(campaign_id, actor, character_id)
        .map_err(|_| PlayCharacterBuildError::Storage)?
    {
        PlayCharacterOwnership::Found { owner } if owner == actor => {}
        PlayCharacterOwnership::Found { .. } | PlayCharacterOwnership::Forbidden => {
            return Err(PlayCharacterBuildError::Forbidden);
        }
        PlayCharacterOwnership::UnknownCampaign => {
            return Err(PlayCharacterBuildError::UnknownCampaign);
        }
        PlayCharacterOwnership::Missing => return Err(PlayCharacterBuildError::Missing),
        _ => return Err(PlayCharacterBuildError::Storage),
    }

    let obj = object(body).map_err(|_| PlayCharacterBuildError::Invalid)?;
    let race = string_field(&obj, "race").map_err(|_| PlayCharacterBuildError::Invalid)?;
    let class = string_field(&obj, "class").map_err(|_| PlayCharacterBuildError::Invalid)?;
    let background =
        string_field(&obj, "background").map_err(|_| PlayCharacterBuildError::Invalid)?;
    let abilities =
        as_object(field(&obj, "abilities").map_err(|_| PlayCharacterBuildError::Invalid)?)
            .map_err(|_| PlayCharacterBuildError::Invalid)?;

    if !matches!(race, "dwarf" | "elf" | "halfling" | "human")
        || !matches!(class, "cleric" | "fighter" | "rogue" | "wizard")
        || !matches!(background, "acolyte" | "criminal" | "sage" | "soldier")
    {
        return Err(PlayCharacterBuildError::Invalid);
    }
    for ability in ["str", "dex", "con", "int", "wis", "cha"] {
        if !(1..=30).contains(
            &number_field(abilities, ability).map_err(|_| PlayCharacterBuildError::Invalid)?,
        ) {
            return Err(PlayCharacterBuildError::Invalid);
        }
    }

    let scores = [
        number_field(abilities, "str").map_err(|_| PlayCharacterBuildError::Invalid)?,
        number_field(abilities, "dex").map_err(|_| PlayCharacterBuildError::Invalid)?,
        number_field(abilities, "con").map_err(|_| PlayCharacterBuildError::Invalid)?,
        number_field(abilities, "int").map_err(|_| PlayCharacterBuildError::Invalid)?,
        number_field(abilities, "wis").map_err(|_| PlayCharacterBuildError::Invalid)?,
        number_field(abilities, "cha").map_err(|_| PlayCharacterBuildError::Invalid)?,
    ];
    let con = scores[2];
    let hp_max = match class {
        "rogue" | "cleric" => 8 + (con - 10).div_euclid(2),
        "fighter" => 10 + (con - 10).div_euclid(2),
        "wizard" => 6 + (con - 10).div_euclid(2),
        _ => unreachable!(),
    };
    storage
        .save_play_character_progress(
            campaign_id,
            character_id,
            class,
            (con - 10).div_euclid(2),
            hp_max,
            &scores,
        )
        .map_err(|_| PlayCharacterBuildError::Storage)?;
    Ok(format!(
        r#"{{"character_id":"{}","race":"{}","class":"{}","background":"{}","level":1,"hp_max":{},"proficiency_bonus":2}}"#,
        escape_json(character_id),
        escape_json(race),
        escape_json(class),
        escape_json(background),
        hp_max
    ))
}

fn skill_check_play_character(
    campaign_id: &str,
    actor: &str,
    character_id: &str,
    body: &str,
    storage: &Storage,
) -> Result<String, PlayCharacterSkillCheckError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(character_id) {
        return Err(PlayCharacterSkillCheckError::Invalid);
    }
    let obj = object(body).map_err(|_| PlayCharacterSkillCheckError::Invalid)?;
    let skill = string_field(&obj, "skill").map_err(|_| PlayCharacterSkillCheckError::Invalid)?;
    let ability =
        string_field(&obj, "ability").map_err(|_| PlayCharacterSkillCheckError::Invalid)?;
    let proficient =
        bool_field(&obj, "proficient").map_err(|_| PlayCharacterSkillCheckError::Invalid)?;
    let roll = number_field(&obj, "roll").map_err(|_| PlayCharacterSkillCheckError::Invalid)?;
    if !matches!(
        skill,
        "acrobatics"
            | "animal-handling"
            | "arcana"
            | "athletics"
            | "deception"
            | "history"
            | "insight"
            | "intimidation"
            | "investigation"
            | "medicine"
            | "nature"
            | "perception"
            | "performance"
            | "persuasion"
            | "religion"
            | "sleight-of-hand"
            | "stealth"
            | "survival"
    ) {
        return Err(PlayCharacterSkillCheckError::Invalid);
    }
    let (score, level) = storage
        .play_character_skill_data(campaign_id, actor, character_id, ability)
        .map_err(|_| PlayCharacterSkillCheckError::Storage)??;
    let modifier = modifier(score)
        .checked_add(if proficient {
            proficiency_bonus(level)
        } else {
            0
        })
        .ok_or(PlayCharacterSkillCheckError::Invalid)?;
    let total = roll
        .checked_add(modifier)
        .ok_or(PlayCharacterSkillCheckError::Invalid)?;
    Ok(format!(
        r#"{{"character_id":"{}","skill":"{}","ability":"{}","modifier":{},"total":{}}}"#,
        escape_json(character_id),
        escape_json(skill),
        escape_json(ability),
        modifier,
        total
    ))
}

