fn award_play_encounter_rewards(
    campaign_id: &str,
    owner: &str,
    encounter_id: &str,
    body: &str,
    storage: &Storage,
) -> Result<String, PlayEncounterRewardError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(encounter_id) {
        return Err(PlayEncounterRewardError::Invalid);
    }
    let object = object(body).map_err(|_| PlayEncounterRewardError::Invalid)?;
    let xp = number_field(&object, "xp").map_err(|_| PlayEncounterRewardError::Invalid)?;
    let loot = array_field(&object, "loot")
        .map_err(|_| PlayEncounterRewardError::Invalid)?
        .iter()
        .map(|entry| {
            let entry = as_object(entry)?;
            let slug = string_field(entry, "slug")?;
            let quantity = number_field(entry, "quantity")?;
            if !valid_campaign_text(slug) || quantity <= 0 {
                return Err(());
            }
            Ok(PlayEncounterLoot {
                slug: slug.to_string(),
                quantity,
            })
        })
        .collect::<Result<Vec<_>, ()>>()
        .map_err(|_| PlayEncounterRewardError::Invalid)?;
    if xp < 0 {
        return Err(PlayEncounterRewardError::Invalid);
    }
    match storage
        .award_play_encounter_rewards(campaign_id, owner, encounter_id, xp, &loot)
        .map_err(|_| PlayEncounterRewardError::Storage)?
    {
        PlayEncounterRewards::Awarded => Ok(format!(
            r#"{{"encounter_id":"{}","xp":{},"loot":[{}]}}"#,
            escape_json(encounter_id),
            xp,
            loot.iter()
                .map(|item| format!(
                    r#"{{"slug":"{}","quantity":{}}}"#,
                    escape_json(&item.slug),
                    item.quantity
                ))
                .collect::<Vec<_>>()
                .join(",")
        )),
        PlayEncounterRewards::UnknownCampaign => Err(PlayEncounterRewardError::UnknownCampaign),
        PlayEncounterRewards::Forbidden => Err(PlayEncounterRewardError::Forbidden),
        PlayEncounterRewards::UnknownEncounter => Err(PlayEncounterRewardError::UnknownEncounter),
        PlayEncounterRewards::Conflict => Err(PlayEncounterRewardError::Conflict),
    }
}

