fn remove_play_encounter_combatant(
    campaign_id: &str,
    owner: &str,
    encounter_id: &str,
    member: &str,
    storage: &Storage,
) -> Result<String, PlayEncounterCombatantError> {
    if !valid_campaign_text(campaign_id)
        || !valid_campaign_text(encounter_id)
        || !valid_campaign_text(member)
    {
        return Err(PlayEncounterCombatantError::Invalid);
    }
    match storage
        .remove_play_encounter_combatant(campaign_id, owner, encounter_id, member)
        .map_err(|_| PlayEncounterCombatantError::Storage)?
    {
        PlayEncounterCombatantRemove::Removed => {
            Ok(format!(r#"{{"removed":"{}"}}"#, escape_json(member)))
        }
        PlayEncounterCombatantRemove::UnknownCampaign => {
            Err(PlayEncounterCombatantError::UnknownCampaign)
        }
        PlayEncounterCombatantRemove::Forbidden => Err(PlayEncounterCombatantError::Forbidden),
        PlayEncounterCombatantRemove::UnknownEncounter => {
            Err(PlayEncounterCombatantError::UnknownEncounter)
        }
        PlayEncounterCombatantRemove::Missing => Err(PlayEncounterCombatantError::Missing),
    }
}

