fn delay_play_encounter_turn(
    campaign_id: &str,
    actor: &str,
    encounter_id: &str,
    body: &str,
    storage: &Storage,
) -> Result<String, PlayEncounterDelayError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(encounter_id) {
        return Err(PlayEncounterDelayError::Invalid);
    }
    let obj = object(body).map_err(|_| PlayEncounterDelayError::Invalid)?;
    // Accept the position spelling used by the public endpoint as well as the
    // index spelling retained by the initial implementation.
    let target_index = number_field(&obj, "position")
        .or_else(|_| number_field(&obj, "index"))
        .or_else(|_| number_field(&obj, "target_index"))
        .or_else(|_| number_field(&obj, "new_index"))
        .map_err(|_| PlayEncounterDelayError::Invalid)?;
    if target_index < 0 {
        return Err(PlayEncounterDelayError::Invalid);
    }
    match storage
        .delay_play_encounter_turn(campaign_id, actor, encounter_id, target_index as usize)
        .map_err(|_| PlayEncounterDelayError::Storage)?
    {
        PlayEncounterDelay::Delayed { order } => Ok(format!(
            r#"{{"order":[{}]}}"#,
            order
                .iter()
                .map(|entry| format!(
                    r#"{{"name":"{}","kind":"{}","initiative":{}}}"#,
                    escape_json(&entry.name),
                    entry.kind,
                    entry.initiative
                ))
                .collect::<Vec<_>>()
                .join(",")
        )),
        PlayEncounterDelay::Invalid => Err(PlayEncounterDelayError::Invalid),
        PlayEncounterDelay::UnknownCampaign => Err(PlayEncounterDelayError::UnknownCampaign),
        PlayEncounterDelay::Forbidden => Err(PlayEncounterDelayError::Forbidden),
        PlayEncounterDelay::UnknownEncounter => Err(PlayEncounterDelayError::UnknownEncounter),
        PlayEncounterDelay::Empty => Err(PlayEncounterDelayError::Empty),
        PlayEncounterDelay::Conflict => Err(PlayEncounterDelayError::Conflict),
    }
}

