fn apply_play_encounter_condition(
    campaign_id: &str,
    owner: &str,
    encounter_id: &str,
    body: &str,
    storage: &Storage,
) -> Result<String, PlayEncounterConditionError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(encounter_id) {
        return Err(PlayEncounterConditionError::Invalid);
    }
    let obj = object(body).map_err(|_| PlayEncounterConditionError::Invalid)?;
    let target = string_field(&obj, "target").map_err(|_| PlayEncounterConditionError::Invalid)?;
    let condition =
        string_field(&obj, "condition").map_err(|_| PlayEncounterConditionError::Invalid)?;
    let duration =
        number_field(&obj, "duration_rounds").map_err(|_| PlayEncounterConditionError::Invalid)?;
    if !valid_campaign_text(target) || !valid_campaign_text(condition) || duration <= 0 {
        return Err(PlayEncounterConditionError::Invalid);
    }
    match storage
        .apply_play_encounter_condition(
            campaign_id,
            owner,
            encounter_id,
            target,
            condition,
            duration,
        )
        .map_err(|_| PlayEncounterConditionError::Storage)?
    {
        PlayEncounterCondition::Applied { conditions } => Ok(format!(
            r#"{{"target":"{}","conditions":[{}]}}"#,
            escape_json(target),
            conditions_json(&conditions)
        )),
        PlayEncounterCondition::UnknownCampaign => {
            Err(PlayEncounterConditionError::UnknownCampaign)
        }
        PlayEncounterCondition::Forbidden => Err(PlayEncounterConditionError::Forbidden),
        PlayEncounterCondition::UnknownEncounter => {
            Err(PlayEncounterConditionError::UnknownEncounter)
        }
        PlayEncounterCondition::Missing => Err(PlayEncounterConditionError::Missing),
    }
}

fn play_encounter_status(
    campaign_id: &str,
    actor: &str,
    encounter_id: &str,
    storage: &Storage,
) -> Result<String, PlayEncounterStatusError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(encounter_id) {
        return Err(PlayEncounterStatusError::Invalid);
    }
    match storage
        .play_encounter_status(campaign_id, actor, encounter_id)
        .map_err(|_| PlayEncounterStatusError::Storage)?
    {
        PlayEncounterStatus::Found {
            round,
            turn_index,
            active,
            order,
            conditions,
        } => {
            let combatant = |value: &PlayEncounterTurnCombatant| {
                format!(
                    r#"{{"name":"{}","kind":"{}","initiative":{}}}"#,
                    escape_json(&value.name),
                    value.kind,
                    value.initiative
                )
            };
            let order = order.iter().map(combatant).collect::<Vec<_>>().join(",");
            let conditions = conditions
                .iter()
                .map(|(target, entries)| {
                    format!(
                        r#""{}":[{}]"#,
                        escape_json(target),
                        conditions_json(entries)
                    )
                })
                .collect::<Vec<_>>()
                .join(",");
            Ok(format!(
                r#"{{"round":{round},"turn_index":{turn_index},"active":{},"order":[{order}],"conditions":{{{conditions}}}}}"#,
                combatant(&active)
            ))
        }
        PlayEncounterStatus::UnknownCampaign => Err(PlayEncounterStatusError::UnknownCampaign),
        PlayEncounterStatus::Forbidden => Err(PlayEncounterStatusError::Forbidden),
        PlayEncounterStatus::UnknownEncounter => Err(PlayEncounterStatusError::UnknownEncounter),
        PlayEncounterStatus::Empty => Err(PlayEncounterStatusError::Empty),
    }
}

fn submit_play_combat_action(
    campaign_id: &str,
    actor: &str,
    encounter_id: &str,
    body: &str,
    storage: &Storage,
) -> Result<String, PlayCombatActionError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(encounter_id) {
        return Err(PlayCombatActionError::Invalid);
    }
    let obj = object(body).map_err(|_| PlayCombatActionError::Invalid)?;
    let action_type = string_field(&obj, "type").map_err(|_| PlayCombatActionError::Invalid)?;
    let target = string_field(&obj, "target").map_err(|_| PlayCombatActionError::Invalid)?;
    let text = string_field(&obj, "text").map_err(|_| PlayCombatActionError::Invalid)?;
    if !matches!(action_type, "attack" | "help" | "dodge" | "ready")
        || !valid_campaign_text(target)
        || !valid_campaign_text(text)
    {
        return Err(PlayCombatActionError::Invalid);
    }
    match storage
        .submit_play_combat_action(campaign_id, actor, encounter_id, action_type, target, text)
        .map_err(|_| PlayCombatActionError::Storage)?
    {
        PlayCombatActionSubmit::Submitted { sequence } => Ok(format!(
            r#"{{"sequence":{sequence},"kind":"combat_action","actor":"{}","type":"{}","target":"{}","text":"{}"}}"#,
            escape_json(actor),
            escape_json(action_type),
            escape_json(target),
            escape_json(text),
        )),
        PlayCombatActionSubmit::UnknownCampaign => Err(PlayCombatActionError::UnknownCampaign),
        PlayCombatActionSubmit::Forbidden => Err(PlayCombatActionError::Forbidden),
        PlayCombatActionSubmit::UnknownEncounter => Err(PlayCombatActionError::UnknownEncounter),
        PlayCombatActionSubmit::Conflict => Err(PlayCombatActionError::Conflict),
    }
}

