fn play_event_json(event: &PlayEvent) -> String {
    match &event.action_type {
        Some(action_type) => format!(
            r#"{{"sequence":{},"kind":"{}","actor":"{}","type":"{}","text":"{}"}}"#,
            event.sequence,
            escape_json(&event.kind),
            escape_json(&event.actor),
            escape_json(action_type),
            escape_json(&event.text)
        ),
        None => format!(
            r#"{{"sequence":{},"kind":"{}","actor":"{}","text":"{}"}}"#,
            event.sequence,
            escape_json(&event.kind),
            escape_json(&event.actor),
            escape_json(&event.text)
        ),
    }
}

fn play_turn(campaign_id: &str, actor: &str, storage: &Storage) -> Result<String, PlayTurnError> {
    if !valid_campaign_text(campaign_id) {
        return Err(PlayTurnError::Invalid);
    }
    match storage
        .play_turn(campaign_id, actor)
        .map_err(|_| PlayTurnError::Storage)?
    {
        PlayTurn::Found {
            current_actor,
            turn_number,
            queue,
            phase,
        } => {
            let queue = queue
                .iter()
                .map(|entry| format!("\"{}\"", escape_json(entry)))
                .collect::<Vec<_>>()
                .join(",");
            Ok(format!(
                r#"{{"campaign_id":"{}","current_actor":"{}","phase":"{}","turn_number":{turn_number},"overdue":false,"logical_deadline":{},"queue":[{queue}]}}"#,
                escape_json(campaign_id),
                escape_json(&current_actor),
                escape_json(&phase),
                turn_number + 1,
            ))
        }
        PlayTurn::UnknownCampaign => Err(PlayTurnError::UnknownCampaign),
        PlayTurn::Forbidden => Err(PlayTurnError::Forbidden),
        PlayTurn::Inactive => Err(PlayTurnError::Inactive),
    }
}

