fn assign_character_equipment(
    campaign_id: &str,
    character_id: &str,
    body: &str,
    storage: &Storage,
) -> Result<String, InventoryError> {
    if !valid_campaign_text(campaign_id) || !valid_campaign_text(character_id) {
        return Err(InventoryError::Invalid);
    }
    let obj = object(body).map_err(|_| InventoryError::Invalid)?;
    let item_slug = string_field(&obj, "item_slug").map_err(|_| InventoryError::Invalid)?;
    let quantity = number_field(&obj, "quantity").map_err(|_| InventoryError::Invalid)?;
    if !valid_campaign_text(item_slug) || quantity <= 0 {
        return Err(InventoryError::Invalid);
    }
    match storage.assign_equipment(campaign_id, character_id, item_slug, quantity) {
        Ok(None) => Err(InventoryError::UnknownCampaign),
        Ok(Some(false)) => Err(InventoryError::UnknownCharacter),
        Ok(Some(true)) => Ok(format!(
            r#"{{"character_id":"{}","item_slug":"{}","quantity":{}}}"#,
            escape_json(character_id),
            escape_json(item_slug),
            quantity
        )),
        Err(()) => Err(InventoryError::Unavailable),
    }
}

