fn campaign_analytics_summary(
    campaign_id: &str,
    storage: &Storage,
) -> Result<String, AnalyticsError> {
    if !valid_campaign_text(campaign_id) {
        return Err(AnalyticsError::Invalid);
    }
    let (
        campaign,
        open_quests,
        friendly_npcs,
        scheduled_sessions,
        inventory_items,
        has_dm,
        has_characters,
        has_next_session,
        has_active_quest,
    ) = storage
        .campaign_analytics(campaign_id)
        .map_err(|_| AnalyticsError::Storage)?
        .ok_or(AnalyticsError::UnknownCampaign)?;
    let readiness_score = (has_dm as i64 * 25)
        + (has_characters as i64 * 25)
        + (has_next_session as i64 * 20)
        + (has_active_quest as i64 * 15);
    Ok(format!(
        r#"{{"campaign_id":"{}","readiness_score":{},"open_quests":{},"friendly_npcs":{},"scheduled_sessions":{},"inventory_items":{}}}"#,
        escape_json(&campaign.id),
        readiness_score,
        open_quests,
        friendly_npcs,
        scheduled_sessions,
        inventory_items
    ))
}

fn campaign_risk_report(
    campaign_id: &str,
    body: &str,
    storage: &Storage,
) -> Result<String, AnalyticsError> {
    if !valid_campaign_text(campaign_id) {
        return Err(AnalyticsError::Invalid);
    }
    let obj = object(body).map_err(|_| AnalyticsError::Invalid)?;
    // Keep the request flag validated even though the stable report schema
    // always exposes all four boolean signals.
    let _include_zeroes =
        bool_field(&obj, "include_zeroes").map_err(|_| AnalyticsError::Invalid)?;
    let (campaign, _, _, _, _, has_dm, has_characters, has_next_session, has_active_quest) =
        storage
            .campaign_analytics(campaign_id)
            .map_err(|_| AnalyticsError::Storage)?
            .ok_or(AnalyticsError::UnknownCampaign)?;
    let missing = [
        ("dm", has_dm),
        ("characters", has_characters),
        ("next_session", has_next_session),
        ("active_quest", has_active_quest),
    ]
    .into_iter()
    .filter_map(|(name, present)| (!present).then_some(format!(r#""{}""#, name)))
    .collect::<Vec<_>>()
    .join(",");
    let risk_level = match missing.is_empty() {
        true => "low",
        false
            if [has_dm, has_characters, has_next_session, has_active_quest]
                .into_iter()
                .filter(|present| !present)
                .count()
                <= 2 =>
        {
            "medium"
        }
        false => "high",
    };
    Ok(format!(
        r#"{{"campaign_id":"{}","risk_level":"{}","missing":[{}],"signals":{{"has_dm":{},"has_characters":{},"has_next_session":{},"has_active_quest":{}}}}}"#,
        escape_json(&campaign.id),
        risk_level,
        missing,
        has_dm,
        has_characters,
        has_next_session,
        has_active_quest
    ))
}

