fn create_npc(
    campaign_id: &str,
    body: &str,
    storage: &Storage,
) -> Result<String, RelationshipError> {
    if !valid_campaign_text(campaign_id) {
        return Err(RelationshipError::Invalid);
    }
    let obj = object(body).map_err(|_| RelationshipError::Invalid)?;
    let npc = Npc {
        id: string_field(&obj, "id")
            .map_err(|_| RelationshipError::Invalid)?
            .to_string(),
        name: string_field(&obj, "name")
            .map_err(|_| RelationshipError::Invalid)?
            .to_string(),
        faction_id: string_field(&obj, "faction_id")
            .map_err(|_| RelationshipError::Invalid)?
            .to_string(),
        disposition: number_field(&obj, "disposition").map_err(|_| RelationshipError::Invalid)?,
    };
    if !valid_campaign_text(&npc.id)
        || !valid_campaign_text(&npc.name)
        || !valid_campaign_text(&npc.faction_id)
    {
        return Err(RelationshipError::Invalid);
    }
    if storage
        .campaign(campaign_id)
        .map_err(|_| RelationshipError::Storage)?
        .is_none()
    {
        return Err(RelationshipError::UnknownCampaign);
    }
    if !storage
        .faction_exists(campaign_id, &npc.faction_id)
        .map_err(|_| RelationshipError::Storage)?
    {
        return Err(RelationshipError::UnknownFaction);
    }
    match storage
        .create_npc(campaign_id, &npc)
        .map_err(|_| RelationshipError::Storage)?
    {
        Some(true) => Ok(npc_json(&npc)),
        Some(false) => Err(RelationshipError::Duplicate),
        None => Err(RelationshipError::UnknownCampaign),
    }
}

fn campaign_relationship_summary(
    campaign_id: &str,
    storage: &Storage,
) -> Result<String, RelationshipError> {
    if !valid_campaign_text(campaign_id) {
        return Err(RelationshipError::Invalid);
    }
    let (factions, npcs, friendly_npcs) = storage
        .relationship_summary(campaign_id)
        .map_err(|_| RelationshipError::Storage)?
        .ok_or(RelationshipError::UnknownCampaign)?;
    Ok(format!(
        r#"{{"campaign_id":"{}","factions":{},"npcs":{},"friendly_npcs":{}}}"#,
        escape_json(campaign_id),
        factions,
        npcs,
        friendly_npcs
    ))
}

