        storage.sql("INSERT INTO play_campaigns(id,name,owner,max_players) VALUES ('campaign','Campaign','dm',2); INSERT INTO play_campaign_members(campaign_id,username,character_id,name,class) VALUES ('campaign','dm','dm-character','DM','wizard'), ('campaign','player','hero','Hero','wizard'); INSERT INTO play_campaign_quests(campaign_id,quest_id,title,state,position) VALUES ('campaign','quest','Quest','completed',0); INSERT INTO play_campaign_quest_rewards(campaign_id,quest_id,xp,awarded) VALUES ('campaign','quest',10,0); INSERT INTO play_campaign_quest_reward_items(campaign_id,quest_id,item_id,quantity,position) VALUES ('campaign','quest','healing-potion',2,0);").unwrap();
