    #[test]
    fn character_currency_is_member_readable_and_owner_transferable() {
        let path = std::env::temp_dir().join(format!("dndrest-currency-{}.db", std::process::id()));
        let _ = std::fs::remove_file(&path);
        let storage = Storage::open(path.to_str().unwrap()).unwrap();
        create_play_campaign(r#"{"id":"play-currency","name":"Currency","max_players":3}"#, "dm", &storage).unwrap();
        create_play_member("play-currency", "player-a", r#"{"character_id":"wizard","name":"Elara","class":"wizard"}"#, &storage).unwrap();
        create_play_member("play-currency", "player-b", r#"{"character_id":"rogue","name":"Aria","class":"rogue"}"#, &storage).unwrap();
        assert_eq!(get_play_currency("play-currency", "player-b", "wizard", &storage).unwrap(), r#"{"character_id":"wizard","gold":10}"#);
        assert_eq!(transfer_play_currency("play-currency", "player-a", "wizard", r#"{"to_character_id":"rogue","gold":3}"#, &storage).unwrap(), r#"{"from_character_id":"wizard","to_character_id":"rogue","gold":3,"from_gold":7,"to_gold":13,"transfer_id":1}"#);
        assert!(matches!(transfer_play_currency("play-currency", "player-b", "wizard", r#"{"to_character_id":"rogue","gold":1}"#, &storage), Err(PlayCurrencyError::Forbidden)));
        assert!(matches!(transfer_play_currency("play-currency", "player-a", "wizard", r#"{"to_character_id":"rogue","gold":8}"#, &storage), Err(PlayCurrencyError::Insufficient)));
        assert_eq!(get_play_currency("play-currency", "player-b", "wizard", &storage).unwrap(), r#"{"character_id":"wizard","gold":7}"#);
        assert_eq!(get_play_currency("play-currency", "player-a", "rogue", &storage).unwrap(), r#"{"character_id":"rogue","gold":13}"#);
        let _ = std::fs::remove_file(path);
    }

    #[test]
    fn transactional_transfers_commit_together_and_simulated_failures_leave_no_record() {
        let path = std::env::temp_dir().join(format!("dndrest-transactional-transfer-{}.db", std::process::id()));
        let _ = std::fs::remove_file(&path);
        let storage = Storage::open(path.to_str().unwrap()).unwrap();
        create_play_campaign(r#"{"id":"play-transactional","name":"Transactional","max_players":3}"#, "dm", &storage).unwrap();
        create_play_member("play-transactional", "player-a", r#"{"character_id":"wizard","name":"Elara","class":"wizard"}"#, &storage).unwrap();
        create_play_member("play-transactional", "player-b", r#"{"character_id":"rogue","name":"Aria","class":"rogue"}"#, &storage).unwrap();
        assert!(matches!(create_transactional_play_transfer("play-transactional", "player-a", r#"{"from_character_id":"wizard","to_character_id":"rogue","amount":2,"simulate_failure":true}"#, &storage), Err(PlayTransactionalTransferError::SimulatedFailure)));
        assert_eq!(get_play_currency("play-transactional", "player-a", "wizard", &storage).unwrap(), r#"{"character_id":"wizard","gold":10}"#);
        assert_eq!(get_transactional_play_transfers("play-transactional", "player-b", &storage).unwrap(), r#"{"transfers":[]}"#);
        assert_eq!(create_transactional_play_transfer("play-transactional", "player-a", r#"{"from_character_id":"wizard","to_character_id":"rogue","amount":2,"simulate_failure":false}"#, &storage).unwrap(), r#"{"from_character_id":"wizard","to_character_id":"rogue","amount":2,"from_gold":8,"to_gold":12,"sequence":1}"#);
        assert_eq!(get_transactional_play_transfers("play-transactional", "dm", &storage).unwrap(), r#"{"transfers":[{"from_character_id":"wizard","to_character_id":"rogue","amount":2,"from_gold":8,"to_gold":12,"sequence":1}]}"#);
        let _ = std::fs::remove_file(path);
    }

