    fn play_character_ownership_is_member_visible_and_owner_transferable() {
        let path = std::env::temp_dir().join(format!("dndrest-owners-{}.db", std::process::id()));
        let _ = std::fs::remove_file(&path);
        let storage = Storage::open(path.to_str().unwrap()).unwrap();
        create_play_campaign(
            r#"{"id":"play-owners","name":"Owners","max_players":2}"#,
            "dm",
            &storage,
        )
        .unwrap();
        create_play_member(
            "play-owners",
            "player-a",
            r#"{"character_id":"play-char-a","name":"Aria","class":"rogue"}"#,
            &storage,
        )
        .unwrap();
        create_play_member(
            "play-owners",
            "player-b",
            r#"{"character_id":"play-char-b","name":"Borin","class":"fighter"}"#,
            &storage,
        )
        .unwrap();
        assert_eq!(
            get_play_character_owner("play-owners", "player-b", "play-char-a", &storage).unwrap(),
            r#"{"character_id":"play-char-a","owner":"player-a"}"#
        );
        assert!(matches!(
            claim_play_character("play-owners", "player-b", "play-char-a", &storage),
            Err(PlayCharacterOwnershipError::Conflict)
        ));
        assert!(matches!(
            transfer_play_character(
                "play-owners",
                "player-b",
                "play-char-a",
                r#"{"new_owner":"player-b"}"#,
                &storage
            ),
            Err(PlayCharacterOwnershipError::Forbidden)
        ));
        assert_eq!(
            transfer_play_character(
                "play-owners",
                "player-a",
                "play-char-a",
                r#"{"new_owner":"player-b"}"#,
                &storage
            )
            .unwrap(),
            r#"{"character_id":"play-char-a","owner":"player-b"}"#
        );
        let _ = std::fs::remove_file(path);
    }

