    #[test]
    fn dm_owner_starts_a_populated_play_campaign_once() {
        let path = std::env::temp_dir().join(format!("dndrest-start-{}.db", std::process::id()));
        let _ = std::fs::remove_file(&path);
        let storage = Storage::open(path.to_str().unwrap()).unwrap();
        create_play_campaign(
            r#"{"id":"play-1","name":"Ashen Road","max_players":3}"#,
            "dm",
            &storage,
        )
        .unwrap();
        assert!(matches!(
            start_play_campaign("play-1", "dm", &storage),
            Err(PlayStartError::Conflict)
        ));
        create_play_member(
            "play-1",
            "player-b",
            r#"{"character_id":"play-char-b","name":"Bryn","class":"wizard"}"#,
            &storage,
        )
        .unwrap();
        create_play_member(
            "play-1",
            "player-a",
            r#"{"character_id":"play-char-a","name":"Aria","class":"rogue"}"#,
            &storage,
        )
        .unwrap();
        assert!(matches!(
            start_play_campaign("play-1", "other-dm", &storage),
            Err(PlayStartError::Forbidden)
        ));
        assert_eq!(
            start_play_campaign("play-1", "dm", &storage).unwrap(),
            r#"{"id":"play-1","status":"active","current_actor":"player-a","turn_number":1}"#
        );
        assert!(matches!(
            start_play_campaign("play-1", "dm", &storage),
            Err(PlayStartError::Conflict)
        ));
        assert!(matches!(
            create_play_member(
                "play-1",
                "player-c",
                r#"{"character_id":"play-char-c","name":"Cyra","class":"cleric"}"#,
                &storage
            ),
            Err(PlayMemberError::Conflict)
        ));
        let _ = std::fs::remove_file(path);
    }

