    #[test]
    fn quests_track_milestones_and_campaign_summary() {
        let path = std::env::temp_dir().join(format!("dndrest-quests-{}.db", std::process::id()));
        let _ = std::fs::remove_file(&path);
        let storage = Storage::open(path.to_str().unwrap()).unwrap();
        create_campaign(r#"{"id":"camp-1","name":"Lost Mine","dm":"dm"}"#, &storage).unwrap();
        assert_eq!(create_quest("camp-1", r#"{"id":"quest-1","title":"Resolve goblin trail ambush","status":"active","milestones":["Find the trail","Confront the ambushers"]}"#, &storage).unwrap(), r#"{"id":"quest-1","title":"Resolve goblin trail ambush","status":"active","milestones_total":2,"milestones_done":0}"#);
        assert_eq!(
            update_quest_progress(
                "camp-1",
                "quest-1",
                r#"{"completed":["Find the trail"]}"#,
                &storage
            )
            .unwrap(),
            r#"{"id":"quest-1","status":"active","milestones_total":2,"milestones_done":1}"#
        );
        assert_eq!(
            campaign_quest_summary("camp-1", &storage).unwrap(),
            r#"{"campaign_id":"camp-1","active":1,"completed":0,"blocked":0}"#
        );
        assert_eq!(
            update_quest_progress(
                "camp-1",
                "quest-1",
                r#"{"completed":["Confront the ambushers"]}"#,
                &storage
            )
            .unwrap(),
            r#"{"id":"quest-1","status":"completed","milestones_total":2,"milestones_done":2}"#
        );
        assert_eq!(
            campaign_quest_summary("camp-1", &storage).unwrap(),
            r#"{"campaign_id":"camp-1","active":0,"completed":1,"blocked":0}"#
        );
        assert!(matches!(
            update_quest_progress(
                "camp-1",
                "quest-1",
                r#"{"completed":["missing"]}"#,
                &storage
            ),
            Err(QuestError::Invalid)
        ));
        let _ = std::fs::remove_file(path);
    }

