    #[test]
    fn scenes_are_owner_controlled_member_readable_and_durable() {
        let path = std::env::temp_dir().join(format!("dndrest-scenes-{}.db", std::process::id()));
        let _ = std::fs::remove_file(&path);
        let storage = Storage::open(path.to_str().unwrap()).unwrap();
        create_play_campaign(
            r#"{"id":"play-1","name":"Ashen Road","max_players":2}"#,
            "dm",
            &storage,
        )
        .unwrap();
        create_play_member(
            "play-1",
            "player",
            r#"{"character_id":"char-1","name":"Aria","class":"rogue"}"#,
            &storage,
        )
        .unwrap();
        assert_eq!(
            create_play_scene(
                "play-1",
                "dm",
                r#"{"id":"cave-entrance","name":"Cave Entrance"}"#,
                &storage
            )
            .unwrap(),
            r#"{"id":"cave-entrance","name":"Cave Entrance","status":"open"}"#
        );
        assert!(matches!(
            create_play_scene(
                "play-1",
                "other",
                r#"{"id":"camp","name":"Camp"}"#,
                &storage
            ),
            Err(PlaySceneError::Forbidden)
        ));
        assert_eq!(
            enter_play_scene("play-1", "dm", "cave-entrance", &storage).unwrap(),
            r#"{"current_scene_id":"cave-entrance","name":"Cave Entrance"}"#
        );
        assert_eq!(
            get_current_play_scene("play-1", "player", &storage).unwrap(),
            r#"{"id":"cave-entrance","name":"Cave Entrance","status":"open"}"#
        );
        assert_eq!(
            close_play_scene("play-1", "dm", "cave-entrance", &storage).unwrap(),
            r#"{"id":"cave-entrance","status":"closed"}"#
        );
        assert!(matches!(
            get_current_play_scene("play-1", "player", &storage),
            Err(PlaySceneError::Missing)
        ));
        assert!(matches!(
            enter_play_scene("play-1", "dm", "cave-entrance", &storage),
            Err(PlaySceneError::Closed)
        ));
        let reopened = Storage::open(path.to_str().unwrap()).unwrap();
        assert!(matches!(
            get_current_play_scene("play-1", "dm", &reopened),
            Err(PlaySceneError::Missing)
        ));
        let _ = std::fs::remove_file(path);
    }

