    #[test]
    fn ending_an_active_encounter_restores_the_saved_exploration_actor_once() {
        let path =
            std::env::temp_dir().join(format!("dndrest-end-encounter-{}.db", std::process::id()));
        let _ = std::fs::remove_file(&path);
        let storage = Storage::open(path.to_str().unwrap()).unwrap();
        create_play_campaign(
            r#"{"id":"play-1","name":"Ashen Road","max_players":2}"#,
            "dm",
            &storage,
        )
        .unwrap();
        create_play_member(
            "play-1",
            "player-a",
            r#"{"character_id":"char-a","name":"Aria","class":"rogue"}"#,
            &storage,
        )
        .unwrap();
        create_play_member(
            "play-1",
            "player-b",
            r#"{"character_id":"char-b","name":"Bryn","class":"wizard"}"#,
            &storage,
        )
        .unwrap();
        start_play_campaign("play-1", "dm", &storage).unwrap();
        storage.sql("UPDATE play_campaign_runtime SET current_actor = 'dm' WHERE campaign_id = 'play-1';").unwrap();
        create_play_encounter(
            "play-1",
            "dm",
            r#"{"id":"enc-road","name":"Road Ambush"}"#,
            &storage,
        )
        .unwrap();
        storage.sql("UPDATE play_campaign_runtime SET current_actor = 'player-b' WHERE campaign_id = 'play-1';").unwrap();
        close_play_encounter("play-1", "dm", "enc-road", &storage).unwrap();

        assert_eq!(
            end_play_encounter("play-1", "dm", "enc-road", &storage).unwrap(),
            r#"{"campaign_id":"play-1","status":"active","phase":"exploration","current_actor":"dm"}"#
        );
        assert_eq!(
            storage
                .sql("SELECT status FROM play_campaign_encounters WHERE id = 'enc-road';")
                .unwrap()
                .trim(),
            "closed"
        );
        assert!(matches!(
            end_play_encounter("play-1", "dm", "enc-road", &storage),
            Err(PlayEncounterEndError::Conflict)
        ));
        assert!(matches!(
            end_play_encounter("play-1", "player-a", "enc-road", &storage),
            Err(PlayEncounterEndError::Forbidden)
        ));
        let _ = std::fs::remove_file(path);
    }

