    #[test]
    fn faction_reputation_is_bounded_durable_and_member_filtered() {
        let path = std::env::temp_dir().join(format!("dndrest-faction-reputation-{}.db", std::process::id()));
        let _ = std::fs::remove_file(&path);
        let storage = Storage::open(path.to_str().unwrap()).unwrap();
        create_play_campaign(r#"{"id":"play-1","name":"Ashen Road","max_players":2}"#, "dm", &storage).unwrap();
        create_play_member("play-1", "player-a", r#"{"character_id":"char-a","name":"Aria","class":"rogue"}"#, &storage).unwrap();
        create_play_member("play-1", "player-b", r#"{"character_id":"char-b","name":"Bryn","class":"wizard"}"#, &storage).unwrap();
        assert_eq!(create_play_faction("play-1", "dm", r#"{"faction_id":"harpers","name":"Harpers"}"#, &storage).unwrap(), r#"{"faction_id":"harpers","name":"Harpers"}"#);
        assert_eq!(change_play_faction_reputation("play-1", "dm", "harpers", r#"{"character_id":"char-a","delta":25,"reason":"rescued-prisoners"}"#, &storage).unwrap(), r#"{"faction_id":"harpers","character_id":"char-a","reputation":25,"delta":25,"reason":"rescued-prisoners"}"#);
        assert_eq!(change_play_faction_reputation("play-1", "dm", "harpers", r#"{"character_id":"char-a","delta":25,"reason":"more-heroics"}"#, &storage).unwrap(), r#"{"faction_id":"harpers","character_id":"char-a","reputation":50,"delta":25,"reason":"more-heroics"}"#);
        change_play_faction_reputation("play-1", "dm", "harpers", r#"{"character_id":"char-b","delta":-10,"reason":"insulted-agent"}"#, &storage).unwrap();
        assert_eq!(get_play_faction_reputation("play-1", "player-a", "harpers", &storage).unwrap(), r#"{"faction_id":"harpers","entries":[{"faction_id":"harpers","character_id":"char-a","reputation":25,"delta":25,"reason":"rescued-prisoners"},{"faction_id":"harpers","character_id":"char-a","reputation":50,"delta":25,"reason":"more-heroics"}]}"#);
        assert!(get_play_faction_reputation("play-1", "dm", "harpers", &storage).unwrap().contains(r#""character_id":"char-b""#));
        assert!(matches!(create_play_faction("play-1", "player-a", r#"{"faction_id":"x","name":"X"}"#, &storage), Err(PlayFactionError::Forbidden)));
        assert!(matches!(change_play_faction_reputation("play-1", "dm", "harpers", r#"{"character_id":"char-a","delta":0,"reason":"nope"}"#, &storage), Err(PlayFactionError::Invalid)));
        assert!(matches!(change_play_faction_reputation("play-1", "dm", "harpers", r#"{"character_id":"missing","delta":1,"reason":"nope"}"#, &storage), Err(PlayFactionError::Invalid)));
        storage.reset().unwrap();
        create_play_campaign(r#"{"id":"play-1","name":"Ashen Road","max_players":2}"#, "dm", &storage).unwrap();
        create_play_member("play-1", "player-a", r#"{"character_id":"char-a","name":"Aria","class":"rogue"}"#, &storage).unwrap();
        assert_eq!(create_play_faction("play-1", "dm", r#"{"faction_id":"harpers","name":"Harpers"}"#, &storage).unwrap(), r#"{"faction_id":"harpers","name":"Harpers"}"#);
        assert_eq!(change_play_faction_reputation("play-1", "dm", "harpers", r#"{"character_id":"char-a","delta":15,"reason":"fresh-start"}"#, &storage).unwrap(), r#"{"faction_id":"harpers","character_id":"char-a","reputation":15,"delta":15,"reason":"fresh-start"}"#);
        let _ = std::fs::remove_file(path);
    }

    #[test]
    fn npc_dialogue_is_ordered_private_to_the_dm_and_durable() {
        let path = std::env::temp_dir().join(format!("dndrest-npc-dialogue-{}.db", std::process::id()));
        let _ = std::fs::remove_file(&path);
        let storage = Storage::open(path.to_str().unwrap()).unwrap();
        create_play_campaign(r#"{"id":"play-1","name":"Ashen Road","max_players":2}"#, "dm", &storage).unwrap();
        create_play_member("play-1", "player-a", r#"{"character_id":"char-a","name":"Aria","class":"rogue"}"#, &storage).unwrap();
        create_play_agenda_npc("play-1", "dm", r#"{"npc_id":"npc-guide","name":"Sildar","agenda":"Help","public_status":"present"}"#, &storage).unwrap();
        assert_eq!(append_play_npc_dialogue("play-1", "dm", "npc-guide", r#"{"dialogue_id":"welcome","speaker":"Sildar","text":"Welcome.","visibility":"public"}"#, &storage).unwrap(), r#"{"dialogue_id":"welcome","speaker":"Sildar","text":"Welcome.","visibility":"public"}"#);
        append_play_npc_dialogue("play-1", "dm", "npc-guide", r#"{"dialogue_id":"secret","speaker":"Sildar","text":"Secret.","visibility":"private"}"#, &storage).unwrap();
        assert_eq!(get_play_npc_dialogue("play-1", "player-a", "npc-guide", &storage).unwrap(), r#"{"npc_id":"npc-guide","entries":[{"dialogue_id":"welcome","speaker":"Sildar","text":"Welcome.","visibility":"public"}]}"#);
        assert!(get_play_npc_dialogue("play-1", "dm", "npc-guide", &storage).unwrap().contains(r#""dialogue_id":"secret""#));
        assert!(matches!(append_play_npc_dialogue("play-1", "player-a", "npc-guide", r#"{"dialogue_id":"nope","speaker":"Sildar","text":"No.","visibility":"public"}"#, &storage), Err(PlayNpcDialogueError::Forbidden)));
        assert!(matches!(append_play_npc_dialogue("play-1", "dm", "npc-guide", r#"{"dialogue_id":"welcome","speaker":"Sildar","text":"Again.","visibility":"public"}"#, &storage), Err(PlayNpcDialogueError::Conflict)));
        let reopened = Storage::open(path.to_str().unwrap()).unwrap();
        assert!(get_play_npc_dialogue("play-1", "dm", "npc-guide", &reopened).unwrap().contains(r#""dialogue_id":"secret""#));
        storage.reset().unwrap();
        create_play_campaign(r#"{"id":"play-1","name":"Ashen Road","max_players":2}"#, "dm", &storage).unwrap();
        create_play_member("play-1", "player-a", r#"{"character_id":"char-a","name":"Aria","class":"rogue"}"#, &storage).unwrap();
        create_play_agenda_npc("play-1", "dm", r#"{"npc_id":"npc-guide","name":"Sildar","agenda":"Help","public_status":"present"}"#, &storage).unwrap();
        assert!(append_play_npc_dialogue("play-1", "dm", "npc-guide", r#"{"dialogue_id":"welcome","speaker":"Sildar","text":"Welcome again.","visibility":"public"}"#, &storage).is_ok());
        let _ = std::fs::remove_file(path);
    }

