        assert_eq!(create_play_relationship("play-relationships", "dm", r#"{"source_id":"npc-guide","target_id":"char-a","kind":"trust","score":25}"#, &storage).unwrap(), r#"{"source_id":"npc-guide","target_id":"char-a","kind":"trust","score":25}"#);
