        assert_eq!(create_play_clue("play-clues", "dm", r#"{"clue_id":"letter","text":"For Aria.","audience":"character","character_id":"char-a"}"#, &storage).unwrap(), r#"{"clue_id":"letter","text":"For Aria.","audience":"character","character_id":"char-a"}"#);
        assert_eq!(create_play_clue("play-clues", "dm", r#"{"clue_id":"party","text":"For everyone.","audience":"party"}"#, &storage).unwrap(), r#"{"clue_id":"party","text":"For everyone.","audience":"party"}"#);
